  moveCleanupCandidate(path.join(HOME, ".agents/Scribe.md"));
  moveSymlinkCleanupCandidate(path.join(HOME, ".config/opencode/agents"));
  moveCleanupCandidate(path.join(HOME, ".config/opencode/plugins/notes-calendar-changes.mjs"));
