function expectedPiExtensionsSource() {
  return `git:${PI_EXTENSIONS_SPEC.repo}@${PI_EXTENSIONS_SPEC.sha}`;
}

function getConfiguredPiExtensionsSources() {
  if (!fs.existsSync(PI_SETTINGS_PATH)) return [];
  const settings = JSON.parse(fs.readFileSync(PI_SETTINGS_PATH, "utf8"));
  const prefix = `git:${PI_EXTENSIONS_SPEC.repo}@`;
  return (settings.packages ?? []).map((entry) => typeof entry === "string" ? entry : entry?.source)
    .filter((source) => typeof source === "string" && source.startsWith(prefix));
}

function inspectPiExtensionsCache() {
  const issues = [];
  const checkout = inspectGitCheckout(PI_EXTENSIONS_CACHE_DIR, PI_EXTENSIONS_SPEC.sha);
  if (!fs.existsSync(path.join(PI_EXTENSIONS_CACHE_DIR, ".git"))) {
    return { healthy: false, dependencyCount: 0, issues: ["checkout missing"] };
  }
  if (checkout.current !== PI_EXTENSIONS_SPEC.sha) {
    issues.push(`SHA mismatch: configured ${PI_EXTENSIONS_SPEC.sha}, cache ${checkout.current?.slice(0, 7) || "missing"}`);
  } else if (!checkout.npmHealthy) {
    issues.push("dependency tree incomplete");
  }

  const packageJsonPath = path.join(PI_EXTENSIONS_PI_EXT_DIR, "package.json");
  let manifest;
  try {
    manifest = JSON.parse(fs.readFileSync(packageJsonPath, "utf8"));
  } catch (error) {
    issues.push(`invalid packages/pi-ext/package.json: ${error.message}`);
    return { healthy: false, dependencyCount: 0, issues };
  }

  const dependencies = Object.keys(manifest.dependencies ?? {});
  if (dependencies.includes("better-sqlite3") && checkout.npmHealthy) {
    const sqliteSmoke = spawnSync(
      "node",
      ["-e", "const Database=require('better-sqlite3'); const db=new Database(':memory:'); db.close()"],
      { cwd: PI_EXTENSIONS_PI_EXT_DIR, stdio: "ignore" },
    );
    if (sqliteSmoke.status !== 0) issues.push("better-sqlite3 native binding unusable");
  }

  return { healthy: issues.length === 0, dependencyCount: dependencies.length, issues };
}

function repairPiExtensionsSqliteBinding() {
  const sqlitePath = path.join(PI_EXTENSIONS_CACHE_DIR, "node_modules", "better-sqlite3");
  if (!pathExistsOrLink(sqlitePath)) return false;
  return run("npm", ["rebuild", "better-sqlite3"], { cwd: PI_EXTENSIONS_CACHE_DIR }) === 0;
}

function runPiExtensionsDoctor() {
  console.log("\nDoctor for pi-extensions package cache");
  const sources = getConfiguredPiExtensionsSources();
  const expectedSource = expectedPiExtensionsSource();
  if (sources.length !== 1 || sources[0] !== expectedSource) {
    console.log(`fail    expected one exact pi-extensions source ${expectedSource}, got ${sources.length ? sources.join(", ") : "none"}`);
    return 1;
  }

  const health = inspectPiExtensionsCache();
  if (health.healthy) {
    console.log(`ok      ${health.dependencyCount} pi-ext runtime dependencies and native binding`);
    return 0;
  }

  console.log(`fail    ${health.issues.join("; ")}`);
  console.log("hint    run ./install.sh --apply --install-deps to repair pi-extensions");
  return 1;
}

function installManagedPackagesPlan() {
  const lock = loadRuntimeLock();
  const plannotator = parseExactNpmSpec(lock.plannotator["pi-extension"]);
  const npmPackages = { [plannotator.name]: plannotator.version, ...lock["pi-packages"].npm };
  for (const [name, version] of Object.entries(npmPackages)) {
    const packageDir = path.join(HOME, ".pi/agent/npm/node_modules", ...name.split("/"));
    let actual = "";
    try { actual = JSON.parse(fs.readFileSync(path.join(packageDir, "package.json"), "utf8")).version; } catch {}
    if (actual === version) continue;
    const source = `npm:${name}@${version}`;
    planAction(state.installDeps ? "repair" : "skip", source, packageDir, actual ? `version ${actual}` : "missing");
    if (state.apply && state.installDeps && run("pi", ["install", source]) !== 0) process.exitCode = 1;
  }
  const piRoot = (() => {
    try { return resolveLockedPiRoot(HOME, process.env.AGENTS_NPM_PREFIX || path.join(HOME, ".local")); } catch { return ""; }
  })();
  if (piRoot) {
    const issues = inspectActivePackageTree({ lock, agentDir: path.join(HOME, ".pi/agent"), piRoot });
    const repairSpecs = npmRepairSpecs(lock, issues);
    if (repairSpecs.length > 0) {
      const npmRoot = path.join(HOME, ".pi/agent/npm");
      planAction(state.installDeps ? "repair" : "skip", repairSpecs.join(" "), npmRoot, issues.map((issue) => issue.message).join("; "));
      if (state.apply && state.installDeps) {
        fs.mkdirSync(npmRoot, { recursive: true });
        const rc = run("npm", ["install", "--save-exact", "--prefix", npmRoot, ...repairSpecs]);
        if (rc !== 0) process.exitCode = rc;
      }
    }
  }
  for (const [name, spec] of Object.entries(lock["pi-packages"].git)) {
    const checkout = path.join(HOME, ".pi/agent/git", spec.repo);
    const health = inspectGitCheckout(checkout, spec.sha);
    const current = health.current || "";
    if (health.healthy) continue;
    const source = `git:${spec.repo}@${spec.sha}`;
    const reason = current !== spec.sha ? (current ? `SHA ${current}` : "missing") : "dependency tree incomplete";
    planAction(state.installDeps ? "repair" : "skip", source, checkout, reason);
    if (!state.apply || !state.installDeps) continue;
    if (!fs.existsSync(path.join(checkout, ".git"))) {
      if (run("pi", ["install", source]) !== 0) process.exitCode = 1;
      continue;
    }
    const repaired = repairGitCheckout({ checkout, sha: spec.sha });
    if (!repaired.ok) {
      console.error(`fail    ${name} checkout repair refused/failed: ${repaired.reason}`);
      process.exitCode = 1;
    }
  }
}

function installPiExtensionsNativePlan() {
  const source = expectedPiExtensionsSource();
  const health = inspectPiExtensionsCache();
  if (health.healthy) {
    planAction("noop", source, PI_EXTENSIONS_CACHE_DIR, "runtime dependencies healthy");
    return;
  }
  const sqliteOnly = health.issues.length === 1
    && health.issues[0] === "better-sqlite3 native binding unusable";
  if (!sqliteOnly) return;
  if (!state.installDeps) {
    planAction("skip", source, PI_EXTENSIONS_CACHE_DIR, "better-sqlite3 native binding unusable; --install-deps not requested");
    return;
  }
  if (!state.apply) {
    planAction("repair", source, PI_EXTENSIONS_CACHE_DIR, "better-sqlite3 native binding unusable");
    return;
  }
  planAction("repair", source, PI_EXTENSIONS_CACHE_DIR, "better-sqlite3 native binding unusable");
  if (!repairPiExtensionsSqliteBinding()) {
    console.error("fail    pi-extensions better-sqlite3 rebuild failed");
    process.exitCode = 1;
    return;
  }
  const repaired = inspectPiExtensionsCache();
  if (!repaired.healthy) {
    console.error(`fail    pi-extensions remains unhealthy: ${repaired.issues.join("; ")}`);
    process.exitCode = 1;
    return;
  }
  console.log("ok      pi-extensions better-sqlite3 binding rebuilt");
}

function runPlannotatorDoctor() {
  let rc = 0;
  console.log("\nDoctor for Plannotator CLI");
  console.log(`info    pinned ${PLANNOTATOR_DEP.version}`);

  const platform = detectPlatform();
  const asset = platform ? PLANNOTATOR_DEP.assets[platform] : null;
  if (asset) console.log(`ok      supported platform ${platform}`);
  else {
    console.log(`fail    platform ${platform ?? "unknown"} not supported by pinned release`);
    return 1;
  }

  if (!fs.existsSync(PLANNOTATOR_BINARY)) {
    console.log("fail    Plannotator CLI missing; run ./install.sh --apply --install-deps");
    return 1;
  }

  const versionResult = spawnSync(PLANNOTATOR_BINARY, ["--version"], { encoding: "utf8" });
  const installedVersion = versionResult.stdout?.trim() ?? "";
  const expectedVersion = `plannotator ${PLANNOTATOR_DEP.version}`;
  if (versionResult.status === 0 && installedVersion === expectedVersion) {
    console.log(`ok      binary version ${PLANNOTATOR_DEP.version}`);
  } else {
    console.log(`fail    binary version ${installedVersion || "unknown"}; expected ${expectedVersion}`);
    rc = 1;
  }

  const digest = sha256File(PLANNOTATOR_BINARY);
  if (digest === asset.sha256) console.log("ok      binary checksum");
  else {
    console.log(`fail    binary checksum ${digest}; expected ${asset.sha256}`);
    rc = 1;
  }

  return rc;
}

function runVisualArtifactDoctor() {
  let rc = 0;
  console.log("\nDoctor for visual-artifact dependency");
  console.log(`info    pinned ${VISUAL_ARTIFACT_DEP.version} from ${VISUAL_ARTIFACT_DEP.repository}`);

  const platform = detectPlatform();
  if (platform && VISUAL_ARTIFACT_DEP.assets[platform]) {
    console.log(`ok      supported platform ${platform}`);
  } else {
    console.log(`warn    platform ${platform ?? "unknown"} not supported by pinned release`);
    rc = 1;
  }

  const binary = VISUAL_ARTIFACT_BINARY;
  if (fs.existsSync(binary)) {
    const versionResult = spawnSync(binary, ["--version"], { encoding: "utf8" });
    const installedVersion = versionResult.stdout?.trim() ?? "";
    if (installedVersion === VISUAL_ARTIFACT_DEP.version) console.log(`ok      binary version ${installedVersion}`);
    else {
      console.log(`warn    binary version ${installedVersion || "unknown"}; expected ${VISUAL_ARTIFACT_DEP.version}`);
      rc = 1;
    }
  } else {
    console.log("warn    visual-artifact CLI binary missing; run ./install.sh --apply --install-deps");
    rc = 1;
  }

  const rendererExport = path.join(VISUAL_ARTIFACT_DATA_DIR, "app/out");
  if (fs.existsSync(rendererExport) && fs.lstatSync(rendererExport).isDirectory()) console.log("ok      renderer export");
  else {
    console.log("warn    renderer export missing; run ./install.sh --apply --install-deps");
    rc = 1;
  }

  const artifactStore = path.join(REPO_ROOT, "agents/skills/visual-artifact/artifacts");
  if (fs.existsSync(artifactStore) && fs.lstatSync(artifactStore).isDirectory()) console.log(`ok      artifact store ${artifactStore}`);
  else {
    console.log("warn    artifact store missing; expected agents/skills/visual-artifact/artifacts");
    rc = 1;
  }

  const versionStamp = path.join(VISUAL_ARTIFACT_DATA_DIR, "VERSION");
  if (!fs.existsSync(versionStamp)) {
    console.log("warn    version stamp missing; run ./install.sh --apply --install-deps");
    rc = 1;
  } else {
    const stampedVersion = fs.readFileSync(versionStamp, "utf8").trim();
    if (stampedVersion === VISUAL_ARTIFACT_DEP.version) console.log(`ok      version stamp ${stampedVersion}`);
    else {
      console.log(`fail    version stamp ${stampedVersion || "empty"}; expected ${VISUAL_ARTIFACT_DEP.version}`);
      rc = 1;
    }
  }

  const liveSettings = path.join(HOME, ".pi/agent/settings.json");
  if (fs.existsSync(liveSettings)) {
    if (fs.lstatSync(liveSettings).isSymbolicLink()) {
      const linkDest = fs.readlinkSync(liveSettings);
      const absDest = path.isAbsolute(linkDest) ? linkDest : path.resolve(path.dirname(liveSettings), linkDest);
      if (absDest === path.join(ACTIVE_BUNDLE_PATH, "settings.json")) console.log("ok      ~/.pi/agent/settings.json -> active profile bundle");
      else console.log(`warn    ~/.pi/agent/settings.json symlink points to ${linkDest}, not active profile settings`);
    } else {
      console.log("warn    ~/.pi/agent/settings.json is a regular file; drift from bundle. Remove or re-run install to sync.");
    }
  } else {
    console.log("warn    ~/.pi/agent/settings.json missing");
  }

  return rc;
}

