  const grep = spawnSync("grep", ["-R", "tailscale[[:space:]]serve", OPENCODE_WEB.dir, "--include=*.sh"], { stdio: "ignore" });
  if (grep.status === 0) {
    console.log("fail    opencode-web has active tailscale serve command");
