function lintPlist(text) {
  const tmp = path.join(os.tmpdir(), `agents-plist-${process.pid}-${Math.random().toString(16).slice(2)}.plist`);
  fs.writeFileSync(tmp, text);
  const result = spawnSync("plutil", ["-lint", tmp], { stdio: "ignore" });
  fs.rmSync(tmp, { force: true });
  if (result.status === 0) {
    console.log("ok      plist template");
    return true;
  }
  console.log("fail    plist template");
  return false;
}

function shellQuote(value) {
  return `'${String(value).replaceAll("'", "'\\''")}'`;
}

function runInstallPlan() {
  if (state.updateSkills && !state.apply) throw new Error("--update-skills requires --apply");
  if (state.apply && (state.installDeps || state.updateSkills)) {
    const upstreamSkillCatalog = refreshUpstreamSkillCatalog({ home: HOME });
    console.log(`ok      upstream skill catalog ${upstreamSkillCatalog.repository}@${upstreamSkillCatalog.commit}`);
  }
  const agentsRc = run("node", [path.join(REPO_ROOT, "scripts/render-agents.mjs"), "--check"]);
  if (agentsRc !== 0) {
    console.error("fail    generated agents are stale; run node scripts/render-agents.mjs --write");
    process.exitCode = agentsRc;
    return;
  }

  const { profile, candidateDir } = buildProfileBundle();
  ensureActiveBaseline(profile, candidateDir);

  console.log(`mode: ${state.apply ? "apply" : "dry-run"}`);
  if (!state.apply) console.log("note: preview only; rerun with --apply to write and activate this profile bundle");
  else if (!state.installDeps) console.log("note: runtime/package updates skipped; add --install-deps when pinned versions or SHAs changed");
  console.log(`backup: ${BACKUP_DIR}`);
  console.log(`${"action".padEnd(16)} ${"target".padEnd(58)} reason`);
  console.log(`${"----------------".padEnd(16)} ${"----------------------------------------------------------".padEnd(58)} ----------------`);

  installCorePlan(ACTIVE_BUNDLE_PATH, profile);
  prepareProfilePointer(profile, candidateDir);
  if (state.withLocalWebGateway) installLocalWebGatewayPlan();
  if (state.withOpencodeWeb) installOpencodeWebPlan();

  planAction("check", path.join(REPO_ROOT, "mcpx-manifests"), "mcpx-manifests/*.json", "validate only");
  const mcpRc = run("node", [path.join(REPO_ROOT, "scripts/render-opencode-mcp.mjs"), "--check"]);
  if (mcpRc !== 0) process.exitCode = mcpRc;

  installDepsPlan();

  if (state.cleanup) cleanupCandidates();
  else console.log("\nCleanup candidates are untouched. Use --cleanup --apply to move them to backup.");

  if (process.exitCode) throw new Error("refusing active profile swap because an earlier install or validation step failed");
  activateProfile(candidateDir);
  installGlobalAgentsMdLink();
  printNextSteps();
}

