function installPlannotatorCliPlan() {
  const platform = detectPlatform();
  const asset = platform ? PLANNOTATOR_DEP.assets[platform] : null;
  planAction("info", "", "plannotator", `pinned ${PLANNOTATOR_DEP.version} (${platform ?? "unknown platform"})`);

  if (!asset) {
    const reason = `platform ${platform ?? "unknown"} not supported by pinned release`;
    planAction("skip", "", PLANNOTATOR_BINARY, reason);
    if (state.apply && state.installDeps) {
      console.error(`fail    Plannotator install: ${reason}`);
      process.exitCode = 1;
    }
    return;
  }

  if (fs.existsSync(PLANNOTATOR_BINARY)) {
    const versionResult = spawnSync(PLANNOTATOR_BINARY, ["--version"], { encoding: "utf8" });
    const installedVersion = versionResult.stdout?.trim() ?? "";
    if (
      versionResult.status === 0 &&
      installedVersion === `plannotator ${PLANNOTATOR_DEP.version}` &&
      sha256File(PLANNOTATOR_BINARY) === asset.sha256
    ) {
      planAction("noop", PLANNOTATOR_BINARY, PLANNOTATOR_BINARY, `version ${PLANNOTATOR_DEP.version} verified`);
      return;
    }
  }

  if (!state.installDeps) {
    planAction("skip", PLANNOTATOR_DEP.installer.url, PLANNOTATOR_BINARY, "--install-deps not requested");
    return;
  }

  if (!commandExists("curl") || !commandExists("bash") || !commandExists("uname")) {
    const reason = "curl/bash/uname required for Plannotator install";
    planAction("skip", PLANNOTATOR_DEP.installer.url, PLANNOTATOR_BINARY, reason);
    if (state.apply) {
      console.error(`fail    Plannotator install: ${reason}`);
      process.exitCode = 1;
    }
    return;
  }

  if (!state.apply) {
    planAction(
      "download",
      PLANNOTATOR_DEP.installer.url,
      PLANNOTATOR_BINARY,
      `would install ${PLANNOTATOR_DEP.version} with official minimal installer`,
    );
    return;
  }

  let tempHome;
  try {
    tempHome = makeTempHome();
    const installerPath = path.join(tempHome, "plannotator-install.sh");
    planAction(
      "download+verify",
      PLANNOTATOR_DEP.installer.url,
      installerPath,
      `checksum ${PLANNOTATOR_DEP.installer.sha256}`,
    );
    const installerBuffer = fetchBuffer(PLANNOTATOR_DEP.installer.url);
    const installerDigest = sha256Buffer(installerBuffer);
    if (installerDigest !== PLANNOTATOR_DEP.installer.sha256) {
      throw new Error(`installer checksum mismatch: ${installerDigest}`);
    }
    fs.writeFileSync(installerPath, installerBuffer, { mode: 0o700 });
    if (run("bash", ["-n", installerPath]) !== 0) {
      throw new Error("official installer syntax check failed");
    }

    const stagedBinDir = path.join(tempHome, ".local/bin");
    const stagedBinary = path.join(stagedBinDir, "plannotator");
    const installEnv = {
      ...process.env,
      HOME: tempHome,
      PATH: `${stagedBinDir}:${process.env.PATH ?? ""}`,
    };
    planAction("stage", installerPath, tempHome, `official minimal install v${PLANNOTATOR_DEP.version}`);
    const installRc = run(
      "bash",
      [
        installerPath,
        "--minimal",
        "--non-interactive",
        "--skip-attestation",
        "--version",
        `v${PLANNOTATOR_DEP.version}`,
      ],
      { env: installEnv, stdio: "inherit" },
    );
    if (installRc !== 0) throw new Error(`official installer exited ${installRc}`);
    if (!fs.existsSync(stagedBinary)) throw new Error("staged binary missing after install");

    const versionResult = spawnSync(stagedBinary, ["--version"], { encoding: "utf8" });
    const installedVersion = versionResult.stdout?.trim() ?? "";
    if (
      versionResult.status !== 0 ||
      installedVersion !== `plannotator ${PLANNOTATOR_DEP.version}`
    ) {
      throw new Error(
        `staged version ${installedVersion || "unknown"} does not match pinned ${PLANNOTATOR_DEP.version}`,
      );
    }
    const binaryDigest = sha256File(stagedBinary);
    if (binaryDigest !== asset.sha256) {
      throw new Error(`staged binary checksum mismatch: ${binaryDigest}`);
    }

    planAction("copy", stagedBinary, PLANNOTATOR_BINARY, "atomic binary install -> ~/.local/bin");
    fs.mkdirSync(path.dirname(PLANNOTATOR_BINARY), { recursive: true });
    const tempBinary = `${PLANNOTATOR_BINARY}.tmp-${process.pid}`;
    fs.copyFileSync(stagedBinary, tempBinary);
    fs.chmodSync(tempBinary, 0o755);
    fs.renameSync(tempBinary, PLANNOTATOR_BINARY);
    console.log(`ok      Plannotator ${PLANNOTATOR_DEP.version} installed`);
  } catch (error) {
    console.error(`fail    Plannotator install: ${error.message}`);
    process.exitCode = 1;
  } finally {
    if (tempHome) fs.rmSync(tempHome, { recursive: true, force: true });
  }
}

function installVisualArtifactCliPlan() {
  const platform = detectPlatform();
  const asset = platform ? VISUAL_ARTIFACT_DEP.assets[platform] : null;
  planAction("info", "", "visual-artifact", `pinned ${VISUAL_ARTIFACT_DEP.version} (${platform ?? "unknown platform"})`);

  if (!asset) {
