function installPlannotatorCliPlan() {
  const platform = detectPlatform();
  const asset = platform ? PLANNOTATOR_DEP.assets[platform] : null;
  planAction("info", "", "plannotator", `pinned ${PLANNOTATOR_DEP.version} (${platform ?? "unknown platform"})`);

  if (!asset) {
    const reason = `platform ${platform ?? "unknown"} not supported by pinned release`;
    planAction("skip", "", PLANNOTATOR_BINARY, reason);
    if (state.apply && state.installDeps) {
      console.error(`fail    Plannotator install: ${reason}`);
      process.exitCode = 1;
    }
    return;
  }

  if (fs.existsSync(PLANNOTATOR_BINARY)) {
    const versionResult = spawnSync(PLANNOTATOR_BINARY, ["--version"], { encoding: "utf8" });
    const installedVersion = versionResult.stdout?.trim() ?? "";
    if (
      versionResult.status === 0 &&
      installedVersion === `plannotator ${PLANNOTATOR_DEP.version}` &&
      sha256File(PLANNOTATOR_BINARY) === asset.sha256
    ) {
      planAction("noop", PLANNOTATOR_BINARY, PLANNOTATOR_BINARY, `version ${PLANNOTATOR_DEP.version} verified`);
      return;
    }
  }

  if (!state.installDeps) {
    planAction("skip", PLANNOTATOR_DEP.installer.url, PLANNOTATOR_BINARY, "--install-deps not requested");
    return;
  }

  if (!commandExists("curl") || !commandExists("bash") || !commandExists("uname")) {
    const reason = "curl/bash/uname required for Plannotator install";
    planAction("skip", PLANNOTATOR_DEP.installer.url, PLANNOTATOR_BINARY, reason);
    if (state.apply) {
      console.error(`fail    Plannotator install: ${reason}`);
      process.exitCode = 1;
    }
    return;
  }

  if (!state.apply) {
    planAction(
      "download",
      PLANNOTATOR_DEP.installer.url,
      PLANNOTATOR_BINARY,
      `would install ${PLANNOTATOR_DEP.version} with official minimal installer`,
    );
    return;
  }

  let tempHome;
  try {
    tempHome = makeTempHome();
    const installerPath = path.join(tempHome, "plannotator-install.sh");
    planAction(
      "download+verify",
      PLANNOTATOR_DEP.installer.url,
      installerPath,
      `checksum ${PLANNOTATOR_DEP.installer.sha256}`,
    );
    const installerBuffer = fetchBuffer(PLANNOTATOR_DEP.installer.url);
    const installerDigest = sha256Buffer(installerBuffer);
    if (installerDigest !== PLANNOTATOR_DEP.installer.sha256) {
      throw new Error(`installer checksum mismatch: ${installerDigest}`);
    }
    fs.writeFileSync(installerPath, installerBuffer, { mode: 0o700 });
    if (run("bash", ["-n", installerPath]) !== 0) {
      throw new Error("official installer syntax check failed");
    }

    const stagedBinDir = path.join(tempHome, ".local/bin");
    const stagedBinary = path.join(stagedBinDir, "plannotator");
    const installEnv = {
      ...process.env,
      HOME: tempHome,
      PATH: `${stagedBinDir}:${process.env.PATH ?? ""}`,
    };
    planAction("stage", installerPath, tempHome, `official minimal install v${PLANNOTATOR_DEP.version}`);
    const installRc = run(
      "bash",
      [
        installerPath,
        "--minimal",
        "--non-interactive",
        "--skip-attestation",
        "--version",
        `v${PLANNOTATOR_DEP.version}`,
      ],
      { env: installEnv, stdio: "inherit" },
    );
    if (installRc !== 0) throw new Error(`official installer exited ${installRc}`);
    if (!fs.existsSync(stagedBinary)) throw new Error("staged binary missing after install");

    const versionResult = spawnSync(stagedBinary, ["--version"], { encoding: "utf8" });
    const installedVersion = versionResult.stdout?.trim() ?? "";
    if (
      versionResult.status !== 0 ||
      installedVersion !== `plannotator ${PLANNOTATOR_DEP.version}`
    ) {
      throw new Error(
        `staged version ${installedVersion || "unknown"} does not match pinned ${PLANNOTATOR_DEP.version}`,
      );
    }
    const binaryDigest = sha256File(stagedBinary);
    if (binaryDigest !== asset.sha256) {
      throw new Error(`staged binary checksum mismatch: ${binaryDigest}`);
    }

    planAction("copy", stagedBinary, PLANNOTATOR_BINARY, "atomic binary install -> ~/.local/bin");
    fs.mkdirSync(path.dirname(PLANNOTATOR_BINARY), { recursive: true });
    const tempBinary = `${PLANNOTATOR_BINARY}.tmp-${process.pid}`;
    fs.copyFileSync(stagedBinary, tempBinary);
    fs.chmodSync(tempBinary, 0o755);
    fs.renameSync(tempBinary, PLANNOTATOR_BINARY);
    console.log(`ok      Plannotator ${PLANNOTATOR_DEP.version} installed`);
  } catch (error) {
    console.error(`fail    Plannotator install: ${error.message}`);
    process.exitCode = 1;
  } finally {
    if (tempHome) fs.rmSync(tempHome, { recursive: true, force: true });
  }
}

function installVisualArtifactCliPlan() {
  const platform = detectPlatform();
  const asset = platform ? VISUAL_ARTIFACT_DEP.assets[platform] : null;
  planAction("info", "", "visual-artifact", `pinned ${VISUAL_ARTIFACT_DEP.version} (${platform ?? "unknown platform"})`);

  if (!asset) {
    const reason = `platform ${platform ?? "unknown"} not supported by pinned release`;
    planAction("skip", "", "visual-artifact", reason);
    if (state.apply && state.installDeps) {
      console.error(`fail    visual-artifact install: ${reason}`);
      process.exitCode = 1;
    }
    return;
  }

  if (!state.installDeps) {
    planAction("skip", asset.url, VISUAL_ARTIFACT_BINARY, "--install-deps not requested");
    return;
  }

  if (!commandExists("curl") || !commandExists("tar") || !commandExists("uname")) {
    const reason = "curl/tar/uname required for external install";
    planAction("skip", "", "visual-artifact", reason);
    if (state.apply) {
      console.error(`fail    visual-artifact install: ${reason}`);
      process.exitCode = 1;
    }
    return;
  }

  if (!state.apply) {
    planAction("download", asset.url, VISUAL_ARTIFACT_BINARY, `would install ${VISUAL_ARTIFACT_DEP.version} (${asset.sha256})`);
    return;
  }

  let tempHome;
  try {
    tempHome = makeTempHome();

    planAction("download", VISUAL_ARTIFACT_DEP.installer.url, path.join(tempHome, "install.sh"), "official release installer");
    const installerBuffer = fetchBuffer(VISUAL_ARTIFACT_DEP.installer.url);
    const installerDigest = sha256Buffer(installerBuffer);
    if (installerDigest !== VISUAL_ARTIFACT_DEP.installer.sha256) {
      throw new Error(`installer checksum mismatch: ${installerDigest}`);
    }
    const installerPath = path.join(tempHome, "install.sh");
    fs.writeFileSync(installerPath, installerBuffer, { mode: 0o700 });

    const archivePath = path.join(tempHome, `visual-artifact-${platform}.tar.gz`);
    planAction("download+verify", asset.url, archivePath, `checksum ${asset.sha256}`);
    const archiveBuffer = fetchBuffer(asset.url);
    const archiveDigest = sha256Buffer(archiveBuffer);
    if (archiveDigest !== asset.sha256) {
      throw new Error(`archive checksum mismatch: ${archiveDigest}`);
    }
    fs.writeFileSync(archivePath, archiveBuffer, { mode: 0o600 });

    const manifest = {
      version: VISUAL_ARTIFACT_DEP.version,
      assets: { [platform]: pathToFileURL(archivePath).href },
    };
    const manifestPath = path.join(tempHome, "latest.json");
    writeJsonAtomic(manifestPath, manifest);

    const installEnv = {
      ...process.env,
      HOME: tempHome,
      VISUAL_ARTIFACT_MANIFEST_URL: pathToFileURL(manifestPath).href,
      VISUAL_ARTIFACT_INSTALL_DIR: path.join(tempHome, ".local/bin"),
      VISUAL_ARTIFACT_DATA_DIR: path.join(tempHome, ".local/share/visual-artifact"),
    };

    planAction("stage", installerPath, tempHome, `install ${VISUAL_ARTIFACT_DEP.version} from verified archive`);
    const installRc = run("sh", [installerPath], { env: installEnv, stdio: "inherit" });
    if (installRc !== 0) {
      throw new Error(`visual-artifact installer exited ${installRc}`);
    }

    const stagedBinary = path.join(tempHome, ".local/bin/visual-artifact");
    const stagedDataDir = path.join(tempHome, ".local/share/visual-artifact");
    const stagedRenderer = path.join(stagedDataDir, "app/out");
    const stagedVersionStamp = path.join(stagedDataDir, "VERSION");

    if (!fs.existsSync(stagedBinary)) throw new Error("staged binary missing after install");
    if (!fs.existsSync(stagedRenderer)) throw new Error("staged renderer export missing after install");

    const installedVersion = spawnSync(stagedBinary, ["--version"], { encoding: "utf8" }).stdout?.trim();
    if (installedVersion !== VISUAL_ARTIFACT_DEP.version) {
      throw new Error(`staged version ${installedVersion || "unknown"} does not match pinned ${VISUAL_ARTIFACT_DEP.version}`);
    }
    const stampedVersion = fs.existsSync(stagedVersionStamp) ? fs.readFileSync(stagedVersionStamp, "utf8").trim() : "";
    if (stampedVersion !== VISUAL_ARTIFACT_DEP.version) {
      throw new Error(`staged version stamp ${stampedVersion || "missing"} does not match pinned ${VISUAL_ARTIFACT_DEP.version}`);
    }

    planAction("copy", stagedBinary, VISUAL_ARTIFACT_BINARY, "atomic binary install -> ~/.local/bin");
    fs.mkdirSync(path.dirname(VISUAL_ARTIFACT_BINARY), { recursive: true });
    const tempBinary = `${VISUAL_ARTIFACT_BINARY}.tmp-${process.pid}`;
    fs.copyFileSync(stagedBinary, tempBinary);
    fs.chmodSync(tempBinary, 0o755);
    fs.renameSync(tempBinary, VISUAL_ARTIFACT_BINARY);

    planAction("copy", stagedRenderer, path.join(VISUAL_ARTIFACT_DATA_DIR, "app/out"), "renderer export -> ~/.local/share/visual-artifact");
    fs.mkdirSync(path.join(VISUAL_ARTIFACT_DATA_DIR, "app"), { recursive: true });
    fs.rmSync(path.join(VISUAL_ARTIFACT_DATA_DIR, "app/out"), { recursive: true, force: true });
    fs.cpSync(stagedRenderer, path.join(VISUAL_ARTIFACT_DATA_DIR, "app/out"), { recursive: true, force: true });
    fs.copyFileSync(stagedVersionStamp, path.join(VISUAL_ARTIFACT_DATA_DIR, "VERSION"));

    console.log(`ok      visual-artifact ${VISUAL_ARTIFACT_DEP.version} installed`);
  } catch (error) {
    console.error(`fail    visual-artifact install: ${error.message}`);
    process.exitCode = 1;
    return;
  } finally {
    if (tempHome) {
      try {
        fs.rmSync(tempHome, { recursive: true, force: true });
      } catch {
        // ignore cleanup failure
      }
    }
  }
}

function installDepsPlan() {
  if (!state.installDeps) return;

  const installCoreDeps = !state.withLocalWebGateway && !state.withOpencodeWeb;

  if (!state.apply) {
    if (installCoreDeps) {
      planAction("skip", "", path.join(HOME, ".config/opencode"), "--install-deps requires --apply");
    }
    if (state.withLocalWebGateway) {
      planAction("skip", "", LOCAL_WEB_GATEWAY.dir, "--install-deps requires --apply");
    }
    return;
  }

  if (installCoreDeps) {
    if (commandExists("bun")) {
      const bunRc = run("bun", ["install"], { cwd: path.join(HOME, ".config/opencode") });
      if (bunRc !== 0) {
        console.error(`fail    bun install exited ${bunRc}`);
        process.exitCode = bunRc;
      }
    } else console.log("warn    bun missing; skipped OpenCode dependency install");
  }

  if (state.withLocalWebGateway) {
    if (commandExists("npm")) {
      const npmRc = run("npm", ["ci"], { cwd: LOCAL_WEB_GATEWAY.dir });
      if (npmRc !== 0) {
        console.error(`fail    npm ci exited ${npmRc}`);
        process.exitCode = npmRc;
      }
    } else console.log("warn    npm missing; skipped local-web-gateway dependency install");
  }
}

function commandExists(command) {
  return spawnSync("sh", ["-lc", `command -v ${shellQuote(command)}`], { stdio: "ignore" }).status === 0;
}

function sha256Buffer(buffer) {
  return crypto.createHash("sha256").update(buffer).digest("hex");
}

function sha256File(file) {
  const hash = crypto.createHash("sha256");
  const fd = fs.openSync(file, "r");
  const buffer = Buffer.allocUnsafe(1024 * 1024);
  try {
    let bytesRead;
    while ((bytesRead = fs.readSync(fd, buffer, 0, buffer.length, null)) > 0) {
      hash.update(buffer.subarray(0, bytesRead));
    }
  } finally {
    fs.closeSync(fd);
  }
  return hash.digest("hex");
}

function fetchBuffer(url) {
  const result = spawnSync("curl", ["-fsSL", "--retry", "3", "--connect-timeout", "10", "--max-time", "120", url], {
    encoding: "buffer",
    maxBuffer: 50 * 1024 * 1024,
  });
  if (result.status !== 0 || !result.stdout) {
    throw new Error(`download failed: ${url}`);
  }
  return result.stdout;
}

function detectPlatform() {
  const osResult = spawnSync("uname", ["-s"], { encoding: "utf8" });
  const archResult = spawnSync("uname", ["-m"], { encoding: "utf8" });
  const rawOs = osResult.stdout?.trim().toLowerCase() ?? "";
  const rawArch = archResult.stdout?.trim().toLowerCase() ?? "";
  const osName = rawOs === "darwin" ? "macos" : rawOs === "linux" ? "linux" : null;
  const archName = rawArch === "x86_64" || rawArch === "amd64" ? "x86_64" : rawArch === "aarch64" || rawArch === "arm64" ? "aarch64" : null;
  if (!osName || !archName) return null;
  return `${osName}-${archName}`;
}

function makeTempHome() {
  const base = path.join(os.tmpdir(), `agents-install-home-${process.pid}-${Date.now()}`);
  fs.mkdirSync(base, { recursive: true });
  fs.mkdirSync(path.join(base, ".pi", "agent", "extensions"), { recursive: true });
  fs.mkdirSync(path.join(base, ".local", "bin"), { recursive: true });
  fs.mkdirSync(path.join(base, ".local", "share"), { recursive: true });
  fs.mkdirSync(path.join(base, ".agents", "skills", "visual-artifact"), { recursive: true });
  return base;
}

function writeJsonAtomic(target, value) {
  const tmp = `${target}.tmp-${process.pid}`;
  fs.writeFileSync(tmp, `${JSON.stringify(value, null, 2)}\n`);
  fs.renameSync(tmp, target);
}

function moveCleanupCandidate(target) {
  if (pathExistsOrLink(target)) {
    planAction("cleanup-backup", "", target, "approved cleanup candidate");
    if (state.apply) backupTarget(target);
  } else {
    planAction("cleanup-noop", "", target, "missing");
  }
}

function moveSymlinkCleanupCandidate(target) {
  if (!pathExistsOrLink(target)) {
    planAction("cleanup-noop", "", target, "missing");
    return;
  }
  if (!fs.lstatSync(target).isSymbolicLink()) {
    planAction("cleanup-skip", "", target, "not a symlink; preserve user-owned directory");
    return;
  }
  moveCleanupCandidate(target);
}

function cleanupCandidates() {
  moveCleanupCandidate(path.join(HOME, ".config/opencode/package-lock.json"));
  moveCleanupCandidate(path.join(HOME, ".config/opencode/command2"));
  moveCleanupCandidate(path.join(HOME, ".agents/plan-mode📝.md"));
  moveCleanupCandidate(path.join(HOME, ".agents/researcher-🤓.md"));
  moveCleanupCandidate(path.join(HOME, ".agents/Scribe.md"));
  moveSymlinkCleanupCandidate(path.join(HOME, ".config/opencode/agents"));
  moveCleanupCandidate(path.join(HOME, ".config/opencode/plugins/notes-calendar-changes.mjs"));
  moveCleanupCandidate(path.join(HOME, ".config/opencode/plugins/note-calendar-changes"));
  console.log("Stale Volta 0.74.1 package removals deferred. No package-manager state touched.");
}

function printNextSteps() {
  console.log("\nNext manual steps:");
  console.log("- Fill secrets/auth files locally; installer never migrates them.");
  console.log(`- Clone notification sounds separately: git@github.com:iurysza/notification-sounds.git -> ${NOTIFICATION_SOUNDS_DIR}`);
  if (state.withLocalWebGateway) {
    console.log("- Start local-web-gateway explicitly when ready: services/local-web-gateway/service.sh start");
    console.log("- Enable Tailscale Serve only via ~/.config/local-web-gateway/env (TAILSCALE_SERVE=1).");
  }
  if (state.withOpencodeWeb) {
    console.log("- Start opencode-web explicitly when ready: services/opencode-web/service.sh start");
    console.log(`- Optional shell integration: source ${OPENCODE_WEB.shellSnippet}`);
  }
}

function runAdoptionMode() {
  if (state.doctor || state.cleanup || state.updateSkills || state.withLocalWebGateway || state.withOpencodeWeb) {
    throw new Error("--adopt cannot be combined with --doctor, --cleanup, or service flags");
  }
  if (state.installDeps && !state.apply) throw new Error("--install-deps requires --apply");
  validateRuntimeLock(DEPENDENCIES);
  validateRuntimeExtensionCatalog({ catalog: RUNTIME_EXTENSION_CATALOG, lock: DEPENDENCIES, repoRoot: REPO_ROOT });
  const profile = resolveInstallProfile();
  if (!pathExistsOrLink(ACTIVE_BUNDLE_PATH)) throw new Error("--adopt requires an installed active profile bundle");
  const activeBundle = fs.realpathSync(ACTIVE_BUNDLE_PATH);
  const expectedBundle = renderExpectedBundle(profile, readBundleUpstreamSkillCatalog(activeBundle));
  try {
    const plan = createAdoptionPlan({
      repoRoot: REPO_ROOT,
      home: HOME,
      profileName: profile.profile,
      expectedBundle,
      activeBundle,
      lock: DEPENDENCIES,
      catalog: RUNTIME_EXTENSION_CATALOG,
    });
    console.log(formatAdoptionPlan(plan));
    if (!state.apply || !plan.hasChanges) return;
    console.log(`adoption backup: ${BACKUP_DIR}`);
    applyAdoptionPlan(plan, { backupDir: path.join(BACKUP_DIR, "adoption") });
    const childArgs = process.argv.slice(2).filter((arg) => arg !== "--adopt");
    const child = spawnSync(process.execPath, [fileURLToPath(import.meta.url), ...childArgs], {
      env: process.env,
      stdio: "inherit",
    });
    if (child.error) throw child.error;
    if (child.status !== 0) throw new Error(`adoption was locked, but profile apply failed with status ${child.status}; fix the reported error and rerun normal apply`);
  } finally {
    fs.rmSync(expectedBundle, { recursive: true, force: true });
  }
}

parseArgs(process.argv.slice(2));

if (state.adopt) {
  runAdoptionMode();
} else if (state.doctor && !state.apply && !state.installDeps && !state.cleanup) {
  process.exit(runDoctor());
} else {
  runInstallPlan();
}
if (!state.adopt && state.doctor) {
  console.log("");
  process.exitCode = runDoctor() || process.exitCode || 0;
}

#!/usr/bin/env node
import { spawnSync } from "node:child_process";
import crypto from "node:crypto";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";
import { resolveProfile } from "./lib/profile-config.mjs";
import { renderProfileBundle } from "./lib/profile-render.mjs";
import { listTrackedSkills, resolveSkillView, writeSkillSymlinks } from "./lib/skill-profile.mjs";
import { loadCachedUpstreamSkillCatalog, refreshUpstreamSkillCatalog } from "./lib/upstream-skill-catalog.mjs";
import { loadRuntimeLock, parseExactNpmSpec, validateRuntimeLock } from "./lib/runtime-lock.mjs";
import { inspectActivePackageTree, inspectGitCheckout, npmRepairSpecs, repairGitCheckout } from "./lib/package-health.mjs";
import { resolveLockedPiRoot } from "./lib/pi-smoke.mjs";
import { linkPiExecutableAnchors } from "./lib/pi-ownership.mjs";
import {
  loadRuntimeExtensionCatalog,
  validateRuntimeExtensionCatalog,
} from "./lib/runtime-activation.mjs";
import { applyAdoptionPlan, createAdoptionPlan, formatAdoptionPlan } from "./lib/adoption.mjs";

const SCRIPT_DIR = path.dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = path.resolve(SCRIPT_DIR, "..");
const HOME = os.homedir();
const STATE_DIR = path.join(HOME, ".local/state/agents");
const PROFILE_STATE_DIR = path.join(STATE_DIR, "profiles");
const ACTIVE_BUNDLE_PATH = path.join(STATE_DIR, "active");

const DEPENDENCIES = JSON.parse(fs.readFileSync(path.join(REPO_ROOT, "dependencies.json"), "utf8"));
const RUNTIME_EXTENSION_CATALOG = loadRuntimeExtensionCatalog(REPO_ROOT);
const PLANNOTATOR_DEP = DEPENDENCIES.plannotator;
const PLANNOTATOR_BINARY = path.join(HOME, ".local/bin/plannotator");
const VISUAL_ARTIFACT_DEP = DEPENDENCIES["visual-artifact"];
const VISUAL_ARTIFACT_BINARY = path.join(HOME, ".local/bin/visual-artifact");
const VISUAL_ARTIFACT_DATA_DIR = path.join(HOME, ".local/share/visual-artifact");
const PI_INSTALLER_URL = process.env.AGENTS_PI_INSTALLER_URL || "https://pi.dev/install.sh";
const OPENCODE_INSTALLER_URL = process.env.AGENTS_OPENCODE_INSTALLER_URL || "https://opencode.ai/install";
const PI_EXTENSIONS_SPEC = DEPENDENCIES["pi-packages"].git["pi-extensions"];
const PI_EXTENSIONS_CACHE_DIR = path.join(HOME, ".pi/agent/git", PI_EXTENSIONS_SPEC.repo);
const PI_EXTENSIONS_PI_EXT_DIR = path.join(PI_EXTENSIONS_CACHE_DIR, "packages/pi-ext");
const PI_SETTINGS_PATH = path.join(HOME, ".pi/agent/settings.json");

const state = {
  apply: false,
  adopt: false,
  doctor: false,
  installDeps: false,
  cleanup: false,
  updateSkills: false,
  withLocalWebGateway: false,
  withOpencodeWeb: false,
  profile: undefined,
};

const MCPX_SERVERS = process.env.MCPX_SERVERS || path.join(HOME, ".config/mcpx/servers");
const NOTIFICATION_SOUNDS_DIR =
  process.env.NOTIFICATION_SOUNDS_DIR || path.join(HOME, ".config/opencode/plugins/notification-sounds");

function resolveInstallProfile() {
  const localSkills = listTrackedSkills(path.join(REPO_ROOT, "agents/skills"));
  return resolveProfile({
    repoRoot: REPO_ROOT,
    cliProfile: state.profile,
    envProfile: process.env.AGENTS_PROFILE,
    trackedSkillNames: localSkills.map((skill) => skill.name),
  });
}

function profileBundleDir(profile) {
  return path.join(PROFILE_STATE_DIR, profile);
}

function atomicBundleStaging(profile) {
  return path.join(STATE_DIR, `.staging-${profile}-${process.pid}`);
}

function buildProfileBundle() {
  const lock = loadRuntimeLock();
  validateRuntimeLock(lock);
  validateRuntimeExtensionCatalog({ catalog: RUNTIME_EXTENSION_CATALOG, lock, repoRoot: REPO_ROOT });
  const profile = resolveInstallProfile();
  const upstreamSkillCatalog = loadCachedUpstreamSkillCatalog({ home: HOME });
  const stagingDir = atomicBundleStaging(profile.profile);
  const resolvedSkills = resolveSkillView({
    repoRoot: REPO_ROOT,
    profile: profile.profile,
    upstreamCatalog: upstreamSkillCatalog,
    overrides: profile.skillOverrides,
  });

  console.log(`profile: ${profile.profile}`);
  console.log(`config source: ${profile.configSource}`);
  console.log(`bundle staging: ${stagingDir}`);
  console.log(`bundle target: ${profileBundleDir(profile.profile)}`);

  if (!state.apply) {
    const validationDir = fs.mkdtempSync(path.join(os.tmpdir(), "agents-profile-validation-"));
    try {
      renderProfileBundle({
        profile: profile.profile,
        lock,
        catalog: profile.catalog,
        defaultModel: profile.defaultModel,
        runtimeActivation: profile.runtimeActivation,
        stagingDir: validationDir,
        home: HOME,
        mcpxServers: MCPX_SERVERS,
        notificationSoundsDir: NOTIFICATION_SOUNDS_DIR,
        upstreamSkillCatalog,
      });
      writeSkillSymlinks(resolvedSkills, path.join(validationDir, "skills"));
    } finally {
      fs.rmSync(validationDir, { recursive: true, force: true });
    }
    return { profile, candidateDir: null };
  }

  fs.rmSync(stagingDir, { recursive: true, force: true });
  fs.mkdirSync(stagingDir, { recursive: true });
  try {
    renderProfileBundle({
      profile: profile.profile,
      lock,
      catalog: profile.catalog,
      defaultModel: profile.defaultModel,
      runtimeActivation: profile.runtimeActivation,
      stagingDir,
      home: HOME,
      mcpxServers: MCPX_SERVERS,
      notificationSoundsDir: NOTIFICATION_SOUNDS_DIR,
      upstreamSkillCatalog,
    });
    writeSkillSymlinks(resolvedSkills, path.join(stagingDir, "skills"));
    const versionsDir = path.join(STATE_DIR, "bundles");
    fs.mkdirSync(versionsDir, { recursive: true });
    fs.mkdirSync(PROFILE_STATE_DIR, { recursive: true });
    const candidateDir = path.join(versionsDir, `${profile.profile}-${Date.now()}-${process.pid}`);
    fs.renameSync(stagingDir, candidateDir);
    return { profile, candidateDir };
  } catch (error) {
    fs.rmSync(stagingDir, { recursive: true, force: true });
    throw error;
  }
}

function replacePointer(pointer, target) {
  fs.mkdirSync(path.dirname(pointer), { recursive: true });
  const temporary = path.join(path.dirname(pointer), `.${path.basename(pointer)}.next-${process.pid}`);
  fs.rmSync(temporary, { force: true });
  fs.symlinkSync(target, temporary);
  try {
    fs.renameSync(temporary, pointer);
  } catch (error) {
    fs.rmSync(temporary, { force: true });
    throw error;
  }
}

function liveBundleFromSettings() {
  const settings = path.join(HOME, ".pi/agent/settings.json");
  try {
    const resolved = fs.realpathSync(settings);
    if (path.basename(resolved) !== "settings.json") return null;
    const bundle = path.dirname(resolved);
    for (const root of [path.join(STATE_DIR, "bundles"), PROFILE_STATE_DIR]) {
      const relative = path.relative(root, bundle);
      if (relative && !relative.startsWith("..") && !path.isAbsolute(relative)) return bundle;
    }
    return null;
  } catch {
    return null;
  }
}

function ensureActiveBaseline(profile, candidateDir) {
  if (!state.apply) return;
  let baseline = pathExistsOrLink(ACTIVE_BUNDLE_PATH) ? fs.realpathSync(ACTIVE_BUNDLE_PATH) : liveBundleFromSettings();
  const selectedPointer = profileBundleDir(profile.profile);
  if (!pathExistsOrLink(ACTIVE_BUNDLE_PATH) && baseline && pathExistsOrLink(selectedPointer) && fs.realpathSync(selectedPointer) !== baseline) {
    throw new Error(`legacy live profile differs from selected ${profile.profile}; apply the currently active profile once before switching`);
  }
  if (!baseline) baseline = candidateDir;
  if (!fs.existsSync(path.join(baseline, "opencode.json"))) {
    const migration = path.join(STATE_DIR, "bundles", `migration-${Date.now()}-${process.pid}`);
    fs.cpSync(baseline, migration, { recursive: true, dereference: false });
    const liveConfig = path.join(HOME, ".config/opencode/opencode.json");
    fs.copyFileSync(fs.existsSync(liveConfig) ? liveConfig : path.join(candidateDir, "opencode.json"), path.join(migration, "opencode.json"));
    baseline = migration;
  }
  if (!pathExistsOrLink(ACTIVE_BUNDLE_PATH) || fs.realpathSync(ACTIVE_BUNDLE_PATH) !== baseline) replacePointer(ACTIVE_BUNDLE_PATH, baseline);
}

function prepareProfilePointer(profile, candidateDir) {
  if (!state.apply) return;
  const target = profileBundleDir(profile.profile);
  if (pathExistsOrLink(target) && !fs.lstatSync(target).isSymbolicLink()) {
    fs.renameSync(target, path.join(STATE_DIR, "bundles", `${profile.profile}-legacy-${Date.now()}`));
  } else if (pathExistsOrLink(target)) {
    fs.mkdirSync(BACKUP_DIR, { recursive: true });
    const backup = path.join(BACKUP_DIR, `profile-${profile.profile}`);
    fs.rmSync(backup, { force: true });
    fs.symlinkSync(fs.realpathSync(target), backup);
  }
  replacePointer(target, candidateDir);
}

function activateProfile(candidateDir) {
  planAction("activate", candidateDir || "candidate bundle", ACTIVE_BUNDLE_PATH, "atomic final profile switch");
  if (!state.apply) return;
  if (process.env.AGENTS_TEST_FAIL_BEFORE_ACTIVE_SWAP === "1") throw new Error("injected failure before active profile swap");
  const previous = pathExistsOrLink(ACTIVE_BUNDLE_PATH) ? fs.realpathSync(ACTIVE_BUNDLE_PATH) : null;
  try {
    replacePointer(ACTIVE_BUNDLE_PATH, candidateDir);
  } catch (error) {
    if (!pathExistsOrLink(ACTIVE_BUNDLE_PATH) && previous) replacePointer(ACTIVE_BUNDLE_PATH, previous);
    throw error;
  }
}
function makeBackupDir() {
  const now = new Date().toISOString().replace(/[-:]/g, "");
  let candidate = path.join(HOME, ".local/state/agents-installer/backups", now);
  let counter = 1;
  while (fs.existsSync(candidate)) {
    candidate = path.join(HOME, ".local/state/agents-installer/backups", `${now}-${counter}`);
    counter += 1;
  }
  return candidate;
}

const BACKUP_DIR = process.env.AGENTS_INSTALLER_BACKUP_DIR || makeBackupDir();

const LOCAL_WEB_GATEWAY = {
  dir: path.join(REPO_ROOT, "services/local-web-gateway"),
  envFile: path.join(HOME, ".config/local-web-gateway/env"),
  routesDir: path.join(HOME, ".config/local-web-gateway/routes.d"),
  stateDir: path.join(HOME, ".local/state/agents/local-web-gateway"),
  label: "com.iurysouza.agents.local-web-gateway",
};
LOCAL_WEB_GATEWAY.plist = path.join(HOME, `Library/LaunchAgents/${LOCAL_WEB_GATEWAY.label}.plist`);

const OPENCODE_WEB = {
  dir: path.join(REPO_ROOT, "services/opencode-web"),
  envFile: path.join(HOME, ".config/opencode-web/env"),
  stateDir: path.join(HOME, ".local/state/agents/opencode-web"),
  shellSnippet: path.join(HOME, ".config/agents/shell/opencode-web.zsh"),
  label: "com.iurysouza.agents.opencode-web",
};
OPENCODE_WEB.plist = path.join(HOME, `Library/LaunchAgents/${OPENCODE_WEB.label}.plist`);

function usage() {
  console.log(`Usage:
  ./install.sh [options]

What it does:
  Renders this repo into the active agent runtime for one profile. By default it
  only previews the plan. Nothing is written unless --apply is present.

Common flows:
  ./install.sh --profile work
      Preview the work profile. Use this before changing runtime config.

  ./install.sh --profile work --apply
      Render and activate the work profile bundle. This updates symlinks and
      profile settings, but does not fetch pinned package/runtime updates.

  ./install.sh --profile work --apply --install-deps
      Full apply. Also installs/updates pinned Pi, OpenCode, git packages,
      npm packages, and external runtime assets. Use this when a package SHA,
      package version, or external dependency changed.

  ./install.sh --doctor --profile work
      Check the selected profile, active bundle, package SHAs, dependency trees,
      Pi/OpenCode versions, and loader smoke tests.

Safety model:
  --dry-run is implicit. --apply is required for writes.
  Secret/auth/env files are never overwritten.
  Cleanup candidates are only moved with --cleanup --apply.
  After enabling/disabling Pi extensions, run /reload or restart Pi.

Options:
  --profile personal|work    Select profile. Overrides AGENTS_PROFILE for this run.
                             Default resolution: AGENTS_PROFILE, then personal.
  --dry-run                  Force preview mode. This is the default.
  --apply                    Perform planned writes and activate the candidate bundle.
  --adopt                    Preview recognized live additions; with --apply, lock and reapply them.
  --doctor                   Run source/dependency/runtime checks instead of install planning.
  --install-deps             With --apply, install/update pinned runtimes, packages, and upstream skills.
  --update-skills            With --apply, fetch and activate the latest upstream skill catalog.
  --cleanup                  With --apply, move approved cleanup candidates to backup.
  -h, --help                 Show this help.

Optional services:
  --with-local-web-gateway   Include services/local-web-gateway install plan.
  --with-opencode-web        Include services/opencode-web install plan.
  --with-local-web           Include both services.
`);
}

function parseArgs(argv) {
  for (let i = 0; i < argv.length; i += 1) {
    const arg = argv[i];
    switch (arg) {
      case "--profile":
        state.profile = argv[++i];
        break;
      case "--apply":
        state.apply = true;
        break;
      case "--adopt":
        state.adopt = true;
        break;
      case "--dry-run":
        state.apply = false;
        break;
      case "--doctor":
        state.doctor = true;
        break;
      case "--install-deps":
        state.installDeps = true;
        break;
      case "--cleanup":
        state.cleanup = true;
        break;
      case "--update-skills":
        state.updateSkills = true;
        break;
      case "--with-local-web-gateway":
        state.withLocalWebGateway = true;
        break;
      case "--with-opencode-web":
        state.withOpencodeWeb = true;
        break;
      case "--with-local-web":
        state.withLocalWebGateway = true;
        state.withOpencodeWeb = true;
        break;
      case "-h":
      case "--help":
        usage();
        process.exit(0);
        break;
      default:
        console.error(`Unknown arg: ${arg}`);
        usage();
        process.exit(2);
    }
  }
}

function relOrAbsolute(target) {
  const rel = path.relative(HOME, target);
  if (!rel.startsWith("..") && !path.isAbsolute(rel)) return rel;
  return `absolute${target.replaceAll(path.sep, "_")}`;
}

function pathExistsOrLink(target) {
  try {
    fs.lstatSync(target);
    return true;
  } catch (error) {
    if (error?.code === "ENOENT") return false;
    throw error;
  }
}

function isDirectory(target) {
  try {
    return fs.lstatSync(target).isDirectory();
  } catch {
    return false;
  }
}

function planAction(type, source, target, reason) {
  console.log(`${type.padEnd(16)} ${target.padEnd(58)} ${reason}`);
  if (source) console.log(`${"".padEnd(16)}   source: ${source}`);
}

function targetIsSecret(target) {
  const normalized = target.split(path.sep).join("/");
  const base = path.basename(target).toLowerCase();
  const explicit = new Set([
    path.join(HOME, ".pi/agent/auth.json"),
    path.join(HOME, ".pi/web-search.json"),
    path.join(HOME, ".pi/agent/web-search.json"),
    path.join(HOME, ".config/ai/secrets.env"),
    path.join(HOME, ".config/opencode/secrets.env"),
  ]);
  return (
    explicit.has(target) ||
    base === ".env" ||
    base === "secrets.env" ||
    base === "auth.json" ||
    base === "web-search.json" ||
    normalized.endsWith("/.env") ||
    normalized.endsWith("/secrets.env") ||
    normalized.endsWith("/auth.json") ||
    normalized.endsWith("/web-search.json")
  );
}

function secretLikePath(target) {
  const normalized = target.split(path.sep).join("/").toLowerCase();
  const base = path.basename(target).toLowerCase();
  return (
    base === ".env" ||
    base === "secrets.env" ||
    base === "auth.json" ||
    base === "web-search.json" ||
    base.includes("cookie") ||
    base.includes("token") ||
    normalized.includes("/google-oauth/")
  );
}

function targetHasSecretDescendant(target) {
  if (!isDirectory(target)) return false;
  const stack = [target];
  while (stack.length) {
    const dir = stack.pop();
    let entries = [];
    try {
      entries = fs.readdirSync(dir, { withFileTypes: true });
    } catch {
      continue;
    }
    for (const entry of entries) {
      const full = path.join(dir, entry.name);
      if (secretLikePath(full)) return true;
      if (entry.isDirectory()) stack.push(full);
    }
  }
  return false;
}

function backupTarget(target) {
  if (targetIsSecret(target)) {
    planAction("skip", "", target, "secret/auth/env target; never backup/move/overwrite");
    return false;
  }
  if (targetHasSecretDescendant(target)) {
    planAction("skip", "", target, "contains secret/auth/env descendant; never backup/move/overwrite");
    return false;
  }
  if (!pathExistsOrLink(target)) return true;
  const backup = path.join(BACKUP_DIR, relOrAbsolute(target));
  if (state.apply) {
    fs.mkdirSync(path.dirname(backup), { recursive: true });
    fs.renameSync(target, backup);
  }
  planAction("backup", "", target, `moved to ${backup}`);
  return true;
}

function sameSymlink(source, target) {
  try {
    const stat = fs.lstatSync(target);
    if (!stat.isSymbolicLink()) return false;
    const dest = fs.readlinkSync(target);
    const absoluteDest = path.resolve(path.dirname(target), dest);
    return absoluteDest === path.resolve(source);
  } catch {
    return false;
  }
}

function installSymlink(source, target) {
  if (!pathExistsOrLink(source)) {
    planAction("missing", source, target, "source missing");
    return false;
  }
  if (sameSymlink(source, target)) {
    planAction("noop", source, target, "already linked");
    return true;
  }
  if (targetIsSecret(target)) {
    planAction("skip", source, target, "secret/auth/env target; never overwrite");
    return true;
  }
  if (targetHasSecretDescendant(target)) {
    planAction("skip", source, target, "contains secret/auth/env descendant; never overwrite");
    return true;
  }
  if (pathExistsOrLink(target)) {
    planAction("backup+link", source, target, "existing different target");
    if (state.apply && backupTarget(target)) {
      fs.mkdirSync(path.dirname(target), { recursive: true });
      fs.symlinkSync(source, target);
    }
    return true;
  }
  planAction("link", source, target, "missing");
  if (state.apply) {
    fs.mkdirSync(path.dirname(target), { recursive: true });
    fs.symlinkSync(source, target);
  }
  return true;
}

function installRequiredProfileLink(source, target, label) {
  if (!state.apply && !pathExistsOrLink(source)) {
    planAction("link", source, target, `planned active ${label} link`);
    return;
  }
  if (!installSymlink(source, target)) throw new Error(`failed to install active ${label} link`);
}

function removeLegacyManagedOpenCodeSecretPlugin() {
  const source = path.join(REPO_ROOT, "opencode/plugins/secret-env-plugin.mjs");
  const target = path.join(HOME, ".config/opencode/plugins/secret-env-plugin.mjs");
  if (!pathExistsOrLink(target)) return true;
  if (!fs.lstatSync(target).isSymbolicLink() || !sameResolvedPath(source, target)) {
    planAction("skip", source, target, "machine-owned plugin target; never replace or remove");
    return true;
  }
  planAction("unlink", source, target, "remove exact legacy installer-owned auto-discovery symlink");
  if (state.apply) fs.unlinkSync(target);
  return true;
}

function renderText(source, extra = {}) {
  const replacements = {
    "{{HOME}}": HOME,
    "{{AGENTS_REPO}}": REPO_ROOT,
    "{{AGENTS_DIR}}": REPO_ROOT,
    "{{MCPX_SERVERS}}": MCPX_SERVERS,
    "{{NOTIFICATION_SOUNDS_DIR}}": NOTIFICATION_SOUNDS_DIR,
    ...extra,
  };
  let text = fs.readFileSync(source, "utf8");
  for (const [key, value] of Object.entries(replacements)) {
    text = text.replaceAll(key, value);
  }
  return text;
}

function renderTemplate(source, target, extra = {}, options = {}) {
  if (!fs.existsSync(source)) {
    planAction("missing", source, target, "template missing");
    return false;
  }
  if (targetIsSecret(target)) {
    planAction("skip", source, target, "secret/auth/env target; never render");
    return true;
  }
  const rendered = renderText(source, extra);
  if (fs.existsSync(target) && fs.readFileSync(target, "utf8") === rendered) {
    planAction("noop", source, target, "rendered content unchanged");
    return true;
  }
  if (pathExistsOrLink(target)) {
    planAction("backup+render", source, target, "template changed or existing target differs");
    if (state.apply && backupTarget(target)) {
      fs.mkdirSync(path.dirname(target), { recursive: true });
      fs.writeFileSync(target, rendered);
    }
    return true;
  }
  planAction("render", source, target, "missing");
  if (state.apply) {
    fs.mkdirSync(path.dirname(target), { recursive: true });
    fs.writeFileSync(target, rendered);
  }
  return true;
}

function copyExampleIfMissing(source, target, { mode } = {}) {
  if (!fs.existsSync(source)) {
    planAction("missing", source, target, "example missing");
    return false;
  }
  if (targetIsSecret(target)) {
    planAction("skip", source, target, "secret/auth/env target; never overwrite");
    return true;
  }
  if (pathExistsOrLink(target)) {
    planAction("skip", source, target, "exists; never overwrite");
    return true;
  }
  planAction("copy-example", source, target, "missing");
  if (state.apply) {
    fs.mkdirSync(path.dirname(target), { recursive: true });
    fs.copyFileSync(source, target);
    if (mode) fs.chmodSync(target, mode);
  }
  return true;
}

function ensureDir(target) {
  if (isDirectory(target)) {
    planAction("noop", "", target, "directory exists");
    return true;
  }
  if (pathExistsOrLink(target)) {
    planAction("skip", "", target, "exists but is not a directory");
    return false;
  }
  planAction("mkdir", "", target, "missing");
  if (state.apply) fs.mkdirSync(target, { recursive: true });
  return true;
}

function run(command, args = [], options = {}) {
  const result = spawnSync(command, args, {
    cwd: options.cwd || REPO_ROOT,
    env: options.env || process.env,
    shell: options.shell || false,
    stdio: options.stdio || "inherit",
    encoding: "utf8",
    detached: options.detached || false,
  });
  return result.status ?? 1;
}

function checkCommand(label, command) {
  const result = spawnSync(command, { shell: true, stdio: "ignore" });
  if (result.status === 0) console.log(`ok      ${label}`);
  else console.log(`warn    ${label}`);
}

function checkSourceJson(source, extra = {}, options = {}) {
  try {
    JSON.parse(renderText(source, extra, options));
    console.log(`ok      json ${source}`);
    return true;
  } catch (error) {
    console.log(`fail    json ${source}: ${error.message}`);
    return false;
  }
}

function sameResolvedPath(source, target) {
  try {
    return fs.realpathSync(source) === fs.realpathSync(target);
  } catch {
    return false;
  }
}

function checkLinkHint(target, source) {
  if (sameSymlink(source, target) || sameResolvedPath(source, target)) console.log(`ok      link ${target}`);
  else console.log(`warn    link ${target} not pointed at repo yet`);
}

function checkRequiredLink(target, source) {
  if (sameSymlink(source, target)) {
    console.log(`ok      active link ${target}`);
    return true;
  }
  console.log(`fail    active link ${target} must point to ${source}`);
  return false;
}

function compareManagedPath(expected, actual, relative = "bundle") {
  if (!pathExistsOrLink(actual)) return `${relative}: missing`;
  const expectedStat = fs.lstatSync(expected);
  const actualStat = fs.lstatSync(actual);
  if (expectedStat.isSymbolicLink()) {
    if (!actualStat.isSymbolicLink()) return `${relative}: expected symlink`;
    return fs.realpathSync(expected) === fs.realpathSync(actual) ? null : `${relative}: symlink target differs`;
  }
  if (expectedStat.isDirectory()) {
    if (!actualStat.isDirectory()) return `${relative}: expected directory`;
    const expectedNames = fs.readdirSync(expected).sort();
    const actualNames = fs.readdirSync(actual).sort();
    if (JSON.stringify(expectedNames) !== JSON.stringify(actualNames)) return `${relative}: entries differ`;
    for (const name of expectedNames) {
      const mismatch = compareManagedPath(path.join(expected, name), path.join(actual, name), `${relative}/${name}`);
      if (mismatch) return mismatch;
    }
    return null;
  }
  if (!actualStat.isFile()) return `${relative}: expected file`;
  return fs.readFileSync(expected).equals(fs.readFileSync(actual)) ? null : `${relative}: content differs`;
}

function readBundleUpstreamSkillCatalog(bundleDir) {
  const metadataPath = path.join(bundleDir, "upstream-skill-catalog.json");
  let metadata;
  try {
    metadata = JSON.parse(fs.readFileSync(metadataPath, "utf8"));
  } catch (error) {
    throw new Error(`invalid bundle upstream catalog metadata: ${error.message}`);
  }
  return loadCachedUpstreamSkillCatalog({ home: HOME, commit: metadata.commit });
}

function renderExpectedBundle(profile, upstreamSkillCatalog) {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), "agents-doctor-expected-"));
  const lock = loadRuntimeLock();
  renderProfileBundle({
    profile: profile.profile,
    lock,
    catalog: profile.catalog,
    defaultModel: profile.defaultModel,
    runtimeActivation: profile.runtimeActivation,
    stagingDir: root,
    home: HOME,
    mcpxServers: MCPX_SERVERS,
    notificationSoundsDir: NOTIFICATION_SOUNDS_DIR,
    upstreamSkillCatalog,
  });
  const skills = resolveSkillView({
    repoRoot: REPO_ROOT,
    profile: profile.profile,
    upstreamCatalog: upstreamSkillCatalog,
    overrides: profile.skillOverrides,
  });
  writeSkillSymlinks(skills, path.join(root, "skills"));
  return root;
}

function installOpencodeCommandLink() {
  const source = path.join(HOME, ".opencode/bin/opencode");
  const target = path.join(HOME, ".local/bin/opencode");
  if (!fs.existsSync(source)) {
    planAction("skip", source, target, "standalone opencode missing");
    return true;
  }
  installSymlink(source, target);
  return true;
}

function checkOpencodeCommandLink() {
  const source = path.join(HOME, ".opencode/bin/opencode");
  const target = path.join(HOME, ".local/bin/opencode");
  if (!fs.existsSync(source)) {
    console.log(`warn    standalone opencode binary ${source}`);
    return;
  }
  checkLinkHint(target, source);
}

function runDoctor() {
  let rc = 0;
  const lock = loadRuntimeLock();
  validateRuntimeLock(lock);
  validateRuntimeExtensionCatalog({ catalog: RUNTIME_EXTENSION_CATALOG, lock, repoRoot: REPO_ROOT });
  const profile = resolveInstallProfile();
  const bundleDir = profileBundleDir(profile.profile);
  console.log(`Doctor for ${REPO_ROOT}`);
  console.log(`profile: ${profile.profile}`);
  console.log(`config source: ${profile.configSource}`);
  console.log(`bundle: ${bundleDir}`);
  try {
    const upstreamSkillCatalog = loadCachedUpstreamSkillCatalog({ home: HOME });
    console.log(`ok      upstream skill catalog ${upstreamSkillCatalog.repository}@${upstreamSkillCatalog.commit}`);
  } catch (error) {
    console.log(`fail    upstream skill catalog: ${error.message}`);
    rc = 1;
  }
  checkCommand("bash", "bash --version");
  checkCommand("node", 'zsh -lic "node --version"');
  checkCommand("pi fresh shell", 'zsh -lic "pi --version"');
  checkCommand("opencode", 'zsh -lic "opencode --version"');
  checkOpencodeCommandLink();
  checkCommand("bun optional", 'zsh -lic "bun --version"');
  checkCommand("git", "git --version");
  checkCommand("gh", "gh --version");
  if (!checkSourceJson(path.join(REPO_ROOT, "opencode/config/opencode.json.tpl"))) rc = 1;
  if (!checkSourceJson(path.join(REPO_ROOT, "opencode/config/opencode-notifier.json.tpl"))) rc = 1;
  if (run("node", [path.join(REPO_ROOT, "scripts/render-agents.mjs"), "--check"]) !== 0) rc = 1;
  if (run("node", [path.join(REPO_ROOT, "scripts/render-opencode-mcp.mjs"), "--check"]) !== 0) rc = 1;
  if (!pathExistsOrLink(ACTIVE_BUNDLE_PATH) || !pathExistsOrLink(bundleDir) || !sameResolvedPath(ACTIVE_BUNDLE_PATH, bundleDir)) {
    console.log(`fail    active profile pointer must resolve to selected profile ${profile.profile}`);
    rc = 1;
  } else {
    console.log(`ok      active profile ${profile.profile}`);
    let expected;
    try {
      const upstreamSkillCatalog = readBundleUpstreamSkillCatalog(fs.realpathSync(ACTIVE_BUNDLE_PATH));
      console.log(`ok      active bundle upstream catalog ${upstreamSkillCatalog.repository}@${upstreamSkillCatalog.commit}`);
      expected = renderExpectedBundle(profile, upstreamSkillCatalog);
    } catch (error) {
      console.log(`fail    active bundle upstream catalog: ${error.message}`);
      rc = 1;
      expected = null;
    }
    try {
      if (expected) {
        const mismatch = compareManagedPath(expected, fs.realpathSync(ACTIVE_BUNDLE_PATH));
        if (mismatch) { console.log(`fail    selected bundle differs from current config: ${mismatch}`); rc = 1; }
        else console.log("ok      selected bundle exactly matches current profile config");
      }
    } finally {
      if (expected) fs.rmSync(expected, { recursive: true, force: true });
    }
  }
  const requiredLinks = [
    [path.join(HOME, ".agents/skills"), path.join(ACTIVE_BUNDLE_PATH, "skills")],
    [path.join(HOME, ".pi/agent/agents"), path.join(ACTIVE_BUNDLE_PATH, "agents")],
    [path.join(HOME, ".pi/agent/AGENTS.md"), path.join(ACTIVE_BUNDLE_PATH, "AGENTS.md")],
    [path.join(HOME, ".pi/agent/model-catalog.json"), path.join(ACTIVE_BUNDLE_PATH, "model-catalog.json")],
    [path.join(HOME, ".pi/agent/settings.json"), path.join(ACTIVE_BUNDLE_PATH, "settings.json")],
    [path.join(HOME, ".pi/agent/extensions"), path.join(ACTIVE_BUNDLE_PATH, "extensions")],
    [path.join(HOME, ".config/opencode/opencode.json"), path.join(ACTIVE_BUNDLE_PATH, "opencode.json")],
  ];
  for (const [target, source] of requiredLinks) if (!checkRequiredLink(target, source)) rc = 1;
  rc = Math.max(rc, runPiExtensionsDoctor());
  rc = Math.max(rc, runPlannotatorDoctor());
  rc = Math.max(rc, runVisualArtifactDoctor());
  rc = Math.max(rc, run("node", [path.join(REPO_ROOT, "scripts/doctor-pi.mjs"), "--profile", profile.profile]));

  if (state.withLocalWebGateway) rc = runLocalWebGatewayDoctor() || rc;
  if (state.withOpencodeWeb) rc = runOpencodeWebDoctor() || rc;
  return rc;
}

function runLocalWebGatewayDoctor() {
  let rc = 0;
  console.log("\nDoctor for services/local-web-gateway");
  checkCommand("local-web-gateway node syntax", `cd ${shellQuote(LOCAL_WEB_GATEWAY.dir)} && node --check local-web-gateway.mjs`);
  checkCommand("local-web-gateway service shell syntax", `bash -n ${shellQuote(path.join(LOCAL_WEB_GATEWAY.dir, "service.sh"))}`);
  checkCommand("local-web-gateway launchd runner syntax", `zsh -n ${shellQuote(path.join(LOCAL_WEB_GATEWAY.dir, "launchd-run.sh"))}`);
  checkCommand("local-web-gateway npm optional", "npm --version");
  const dependency = spawnSync("node", ["-e", "import('http-proxy')"], { cwd: LOCAL_WEB_GATEWAY.dir, stdio: "ignore" });
  if (dependency.status === 0) console.log("ok      local-web-gateway dependency http-proxy");
  else console.log("warn    local-web-gateway dependency http-proxy missing; run --install-deps with --apply");
  const plist = renderText(path.join(LOCAL_WEB_GATEWAY.dir, "templates/com.iurysouza.agents.local-web-gateway.plist.tpl"), {
    "{{SERVICE_DIR}}": LOCAL_WEB_GATEWAY.dir,
    "{{ENV_FILE}}": LOCAL_WEB_GATEWAY.envFile,
    "{{STATE_DIR}}": LOCAL_WEB_GATEWAY.stateDir,
    "{{LAUNCHD_LABEL}}": LOCAL_WEB_GATEWAY.label,
  });
  if (!lintPlist(plist)) rc = 1;
  return rc;
}

function expectedPiExtensionsSource() {
  return `git:${PI_EXTENSIONS_SPEC.repo}@${PI_EXTENSIONS_SPEC.sha}`;
}

function getConfiguredPiExtensionsSources() {
  if (!fs.existsSync(PI_SETTINGS_PATH)) return [];
  const settings = JSON.parse(fs.readFileSync(PI_SETTINGS_PATH, "utf8"));
  const prefix = `git:${PI_EXTENSIONS_SPEC.repo}@`;
  return (settings.packages ?? []).map((entry) => typeof entry === "string" ? entry : entry?.source)
    .filter((source) => typeof source === "string" && source.startsWith(prefix));
}

function inspectPiExtensionsCache() {
  const issues = [];
  const checkout = inspectGitCheckout(PI_EXTENSIONS_CACHE_DIR, PI_EXTENSIONS_SPEC.sha);
  if (!fs.existsSync(path.join(PI_EXTENSIONS_CACHE_DIR, ".git"))) {
    return { healthy: false, dependencyCount: 0, issues: ["checkout missing"] };
  }
  if (checkout.current !== PI_EXTENSIONS_SPEC.sha) {
    issues.push(`SHA mismatch: configured ${PI_EXTENSIONS_SPEC.sha}, cache ${checkout.current?.slice(0, 7) || "missing"}`);
  } else if (!checkout.npmHealthy) {
    issues.push("dependency tree incomplete");
  }

  const packageJsonPath = path.join(PI_EXTENSIONS_PI_EXT_DIR, "package.json");
  let manifest;
  try {
    manifest = JSON.parse(fs.readFileSync(packageJsonPath, "utf8"));
  } catch (error) {
    issues.push(`invalid packages/pi-ext/package.json: ${error.message}`);
    return { healthy: false, dependencyCount: 0, issues };
  }

  const dependencies = Object.keys(manifest.dependencies ?? {});
  if (dependencies.includes("better-sqlite3") && checkout.npmHealthy) {
    const sqliteSmoke = spawnSync(
      "node",
      ["-e", "const Database=require('better-sqlite3'); const db=new Database(':memory:'); db.close()"],
      { cwd: PI_EXTENSIONS_PI_EXT_DIR, stdio: "ignore" },
    );
    if (sqliteSmoke.status !== 0) issues.push("better-sqlite3 native binding unusable");
  }

  return { healthy: issues.length === 0, dependencyCount: dependencies.length, issues };
}

function repairPiExtensionsSqliteBinding() {
  const sqlitePath = path.join(PI_EXTENSIONS_CACHE_DIR, "node_modules", "better-sqlite3");
  if (!pathExistsOrLink(sqlitePath)) return false;
  return run("npm", ["rebuild", "better-sqlite3"], { cwd: PI_EXTENSIONS_CACHE_DIR }) === 0;
}

function runPiExtensionsDoctor() {
  console.log("\nDoctor for pi-extensions package cache");
  const sources = getConfiguredPiExtensionsSources();
  const expectedSource = expectedPiExtensionsSource();
  if (sources.length !== 1 || sources[0] !== expectedSource) {
    console.log(`fail    expected one exact pi-extensions source ${expectedSource}, got ${sources.length ? sources.join(", ") : "none"}`);
    return 1;
  }

  const health = inspectPiExtensionsCache();
  if (health.healthy) {
    console.log(`ok      ${health.dependencyCount} pi-ext runtime dependencies and native binding`);
    return 0;
  }

  console.log(`fail    ${health.issues.join("; ")}`);
  console.log("hint    run ./install.sh --apply --install-deps to repair pi-extensions");
  return 1;
}

function installManagedPackagesPlan() {
  const lock = loadRuntimeLock();
  const plannotator = parseExactNpmSpec(lock.plannotator["pi-extension"]);
  const npmPackages = { [plannotator.name]: plannotator.version, ...lock["pi-packages"].npm };
  for (const [name, version] of Object.entries(npmPackages)) {
    const packageDir = path.join(HOME, ".pi/agent/npm/node_modules", ...name.split("/"));
    let actual = "";
    try { actual = JSON.parse(fs.readFileSync(path.join(packageDir, "package.json"), "utf8")).version; } catch {}
    if (actual === version) continue;
    const source = `npm:${name}@${version}`;
    planAction(state.installDeps ? "repair" : "skip", source, packageDir, actual ? `version ${actual}` : "missing");
    if (state.apply && state.installDeps && run("pi", ["install", source]) !== 0) process.exitCode = 1;
  }
  const piRoot = (() => {
    try { return resolveLockedPiRoot(HOME, process.env.AGENTS_NPM_PREFIX || path.join(HOME, ".local")); } catch { return ""; }
  })();
  if (piRoot) {
    const issues = inspectActivePackageTree({ lock, agentDir: path.join(HOME, ".pi/agent"), piRoot });
    const repairSpecs = npmRepairSpecs(lock, issues);
    if (repairSpecs.length > 0) {
      const npmRoot = path.join(HOME, ".pi/agent/npm");
      planAction(state.installDeps ? "repair" : "skip", repairSpecs.join(" "), npmRoot, issues.map((issue) => issue.message).join("; "));
      if (state.apply && state.installDeps) {
        fs.mkdirSync(npmRoot, { recursive: true });
        const rc = run("npm", ["install", "--save-exact", "--prefix", npmRoot, ...repairSpecs]);
        if (rc !== 0) process.exitCode = rc;
      }
    }
  }
  for (const [name, spec] of Object.entries(lock["pi-packages"].git)) {
    const checkout = path.join(HOME, ".pi/agent/git", spec.repo);
    const health = inspectGitCheckout(checkout, spec.sha);
    const current = health.current || "";
    if (health.healthy) continue;
    const source = `git:${spec.repo}@${spec.sha}`;
    const reason = current !== spec.sha ? (current ? `SHA ${current}` : "missing") : "dependency tree incomplete";
    planAction(state.installDeps ? "repair" : "skip", source, checkout, reason);
    if (!state.apply || !state.installDeps) continue;
    if (!fs.existsSync(path.join(checkout, ".git"))) {
      if (run("pi", ["install", source]) !== 0) process.exitCode = 1;
      continue;
    }
    const repaired = repairGitCheckout({ checkout, sha: spec.sha });
    if (!repaired.ok) {
      console.error(`fail    ${name} checkout repair refused/failed: ${repaired.reason}`);
      process.exitCode = 1;
    }
  }
}

function installPiExtensionsNativePlan() {
  const source = expectedPiExtensionsSource();
  const health = inspectPiExtensionsCache();
  if (health.healthy) {
    planAction("noop", source, PI_EXTENSIONS_CACHE_DIR, "runtime dependencies healthy");
    return;
  }
  const sqliteOnly = health.issues.length === 1
    && health.issues[0] === "better-sqlite3 native binding unusable";
  if (!sqliteOnly) return;
  if (!state.installDeps) {
    planAction("skip", source, PI_EXTENSIONS_CACHE_DIR, "better-sqlite3 native binding unusable; --install-deps not requested");
    return;
  }
  if (!state.apply) {
    planAction("repair", source, PI_EXTENSIONS_CACHE_DIR, "better-sqlite3 native binding unusable");
    return;
  }
  planAction("repair", source, PI_EXTENSIONS_CACHE_DIR, "better-sqlite3 native binding unusable");
  if (!repairPiExtensionsSqliteBinding()) {
    console.error("fail    pi-extensions better-sqlite3 rebuild failed");
    process.exitCode = 1;
    return;
  }
  const repaired = inspectPiExtensionsCache();
  if (!repaired.healthy) {
    console.error(`fail    pi-extensions remains unhealthy: ${repaired.issues.join("; ")}`);
    process.exitCode = 1;
    return;
  }
  console.log("ok      pi-extensions better-sqlite3 binding rebuilt");
}

function runPlannotatorDoctor() {
  let rc = 0;
  console.log("\nDoctor for Plannotator CLI");
  console.log(`info    pinned ${PLANNOTATOR_DEP.version}`);

  const platform = detectPlatform();
  const asset = platform ? PLANNOTATOR_DEP.assets[platform] : null;
  if (asset) console.log(`ok      supported platform ${platform}`);
  else {
    console.log(`fail    platform ${platform ?? "unknown"} not supported by pinned release`);
    return 1;
  }

  if (!fs.existsSync(PLANNOTATOR_BINARY)) {
    console.log("fail    Plannotator CLI missing; run ./install.sh --apply --install-deps");
    return 1;
  }

  const versionResult = spawnSync(PLANNOTATOR_BINARY, ["--version"], { encoding: "utf8" });
  const installedVersion = versionResult.stdout?.trim() ?? "";
  const expectedVersion = `plannotator ${PLANNOTATOR_DEP.version}`;
  if (versionResult.status === 0 && installedVersion === expectedVersion) {
    console.log(`ok      binary version ${PLANNOTATOR_DEP.version}`);
  } else {
    console.log(`fail    binary version ${installedVersion || "unknown"}; expected ${expectedVersion}`);
    rc = 1;
  }

  const digest = sha256File(PLANNOTATOR_BINARY);
  if (digest === asset.sha256) console.log("ok      binary checksum");
  else {
    console.log(`fail    binary checksum ${digest}; expected ${asset.sha256}`);
    rc = 1;
  }

  return rc;
}

function runVisualArtifactDoctor() {
  let rc = 0;
  console.log("\nDoctor for visual-artifact dependency");
  console.log(`info    pinned ${VISUAL_ARTIFACT_DEP.version} from ${VISUAL_ARTIFACT_DEP.repository}`);

