function lintPlist(text) {
  const tmp = path.join(os.tmpdir(), `agents-plist-${process.pid}-${Math.random().toString(16).slice(2)}.plist`);
  fs.writeFileSync(tmp, text);
  const result = spawnSync("plutil", ["-lint", tmp], { stdio: "ignore" });
  fs.rmSync(tmp, { force: true });
  if (result.status === 0) {
    console.log("ok      plist template");
    return true;
  }
  console.log("fail    plist template");
  return false;
}

