function installAgentClisPlan() {
  const lock = loadRuntimeLock();
  validateRuntimeLock(lock);

  const piPackage = lock.pi.package;
  const piVersion = lock.pi.version;
  const opencodeVersion = lock.opencode.version;

  if (!state.installDeps) {
    planAction("skip", piPackage, "pi", "--install-deps not requested");
    planAction("skip", OPENCODE_INSTALLER_URL, path.join(HOME, ".opencode/bin/opencode"), "--install-deps not requested");
    return;
  }

  // Pi: exact locked package via Volta when available, otherwise the explicit user-local prefix.
  const piTarget = path.join(HOME, ".pi/agent/bin/pi");
  const localBinPi = path.join(HOME, ".local/bin/pi");
  if (!state.apply) {
    planAction("install", piPackage, piTarget, `would install Pi ${piVersion}`);
  } else {
    try {
      let canonicalPi;
      if (commandExists("volta")) {
        planAction("install", piPackage, piTarget, `Volta install Pi ${piVersion}`);
        const rc = run("volta", ["install", piPackage]);
        if (rc !== 0) throw new Error(`Volta install exited ${rc}`);
        canonicalPi = path.join(HOME, ".volta/bin/pi");
      } else {
        const prefix = process.env.AGENTS_NPM_PREFIX || path.join(HOME, ".local");
        canonicalPi = path.join(prefix, "bin/pi");
        planAction("install", piPackage, piTarget, `npm user-prefix install Pi ${piVersion}`);
        const rc = run("npm", ["install", "--global", "--prefix", prefix, piPackage]);
        if (rc !== 0) throw new Error(`npm user-prefix install exited ${rc}`);
      }
      linkPiExecutableAnchors(canonicalPi, [piTarget, localBinPi]);
      const versionResult = spawnSync("sh", ["-lc", "pi --version"], { encoding: "utf8" });
      if ((versionResult.stdout?.trim() ?? "") !== piVersion) {
        throw new Error(`Pi version mismatch: got ${versionResult.stdout?.trim()}, expected ${piVersion}`);
      }
      console.log(`ok      Pi ${piVersion} installed`);
    } catch (error) {
      console.error(`fail    Pi install: ${error.message}`);
      process.exitCode = 1;
    }
  }

  // OpenCode: official installer with exact --version
  const opencodeTarget = path.join(HOME, ".opencode/bin/opencode");
  if (!commandExists("curl") || !commandExists("bash")) {
    planAction("skip", OPENCODE_INSTALLER_URL, opencodeTarget, "curl and bash are required");
    if (state.apply) process.exitCode = 1;
    return;
  }
  if (!state.apply) {
    planAction("download", OPENCODE_INSTALLER_URL, opencodeTarget, `would install OpenCode ${opencodeVersion}`);
    return;
  }

  const tempDir = fs.mkdtempSync(path.join(os.tmpdir(), "agents-opencode-installer-"));
  const installerPath = path.join(tempDir, "install.sh");
  try {
    planAction("download", OPENCODE_INSTALLER_URL, installerPath, `OpenCode ${opencodeVersion} installer`);
    fs.writeFileSync(installerPath, fetchBuffer(OPENCODE_INSTALLER_URL), { mode: 0o700 });
    if (run("bash", ["-n", installerPath]) !== 0) {
      throw new Error("OpenCode installer syntax check failed");
    }
    planAction("install", installerPath, opencodeTarget, `OpenCode ${opencodeVersion}`);
    const installRc = run("bash", [installerPath, "--no-modify-path", "--version", opencodeVersion], { detached: true });
    if (installRc !== 0) throw new Error(`OpenCode installer exited ${installRc}`);
    const versionResult = spawnSync(opencodeTarget, ["--version"], { encoding: "utf8" });
    const installedVersion = versionResult.stdout?.trim() || "";
    if (versionResult.status !== 0 || installedVersion !== opencodeVersion) {
      throw new Error(`OpenCode verification expected ${opencodeVersion}, got ${installedVersion || "unavailable"}`);
    }
    console.log(`ok      OpenCode ${opencodeVersion} installed`);
  } catch (error) {
    console.error(`fail    OpenCode install: ${error.message}`);
    process.exitCode = 1;
  } finally {
    fs.rmSync(tempDir, { recursive: true, force: true });
  }
}

