function runDoctor() {
  let rc = 0;
  const lock = loadRuntimeLock();
  validateRuntimeLock(lock);
  validateRuntimeExtensionCatalog({ catalog: RUNTIME_EXTENSION_CATALOG, lock, repoRoot: REPO_ROOT });
  const profile = resolveInstallProfile();
  const bundleDir = profileBundleDir(profile.profile);
  console.log(`Doctor for ${REPO_ROOT}`);
  console.log(`profile: ${profile.profile}`);
  console.log(`config source: ${profile.configSource}`);
  console.log(`bundle: ${bundleDir}`);
  try {
    const upstreamSkillCatalog = loadCachedUpstreamSkillCatalog({ home: HOME });
    console.log(`ok      upstream skill catalog ${upstreamSkillCatalog.repository}@${upstreamSkillCatalog.commit}`);
  } catch (error) {
    console.log(`fail    upstream skill catalog: ${error.message}`);
    rc = 1;
  }
  checkCommand("bash", "bash --version");
  checkCommand("node", 'zsh -lic "node --version"');
  checkCommand("pi fresh shell", 'zsh -lic "pi --version"');
  checkCommand("opencode", 'zsh -lic "opencode --version"');
  checkOpencodeCommandLink();
  checkCommand("bun optional", 'zsh -lic "bun --version"');
  checkCommand("git", "git --version");
  checkCommand("gh", "gh --version");
  if (!checkSourceJson(path.join(REPO_ROOT, "opencode/config/opencode.json.tpl"))) rc = 1;
  if (!checkSourceJson(path.join(REPO_ROOT, "opencode/config/opencode-notifier.json.tpl"))) rc = 1;
  if (run("node", [path.join(REPO_ROOT, "scripts/render-agents.mjs"), "--check"]) !== 0) rc = 1;
  if (run("node", [path.join(REPO_ROOT, "scripts/render-opencode-mcp.mjs"), "--check"]) !== 0) rc = 1;
  if (!pathExistsOrLink(ACTIVE_BUNDLE_PATH) || !pathExistsOrLink(bundleDir) || !sameResolvedPath(ACTIVE_BUNDLE_PATH, bundleDir)) {
    console.log(`fail    active profile pointer must resolve to selected profile ${profile.profile}`);
    rc = 1;
  } else {
    console.log(`ok      active profile ${profile.profile}`);
    let expected;
    try {
      const upstreamSkillCatalog = readBundleUpstreamSkillCatalog(fs.realpathSync(ACTIVE_BUNDLE_PATH));
      console.log(`ok      active bundle upstream catalog ${upstreamSkillCatalog.repository}@${upstreamSkillCatalog.commit}`);
      expected = renderExpectedBundle(profile, upstreamSkillCatalog);
    } catch (error) {
      console.log(`fail    active bundle upstream catalog: ${error.message}`);
      rc = 1;
      expected = null;
    }
    try {
      if (expected) {
        const mismatch = compareManagedPath(expected, fs.realpathSync(ACTIVE_BUNDLE_PATH));
        if (mismatch) { console.log(`fail    selected bundle differs from current config: ${mismatch}`); rc = 1; }
        else console.log("ok      selected bundle exactly matches current profile config");
      }
    } finally {
      if (expected) fs.rmSync(expected, { recursive: true, force: true });
    }
  }
  const requiredLinks = [
    [path.join(HOME, ".agents/skills"), path.join(ACTIVE_BUNDLE_PATH, "skills")],
    [path.join(HOME, ".pi/agent/agents"), path.join(ACTIVE_BUNDLE_PATH, "agents")],
    [path.join(HOME, ".pi/agent/AGENTS.md"), path.join(ACTIVE_BUNDLE_PATH, "AGENTS.md")],
    [path.join(HOME, ".pi/agent/model-catalog.json"), path.join(ACTIVE_BUNDLE_PATH, "model-catalog.json")],
    [path.join(HOME, ".pi/agent/settings.json"), path.join(ACTIVE_BUNDLE_PATH, "settings.json")],
    [path.join(HOME, ".pi/agent/extensions"), path.join(ACTIVE_BUNDLE_PATH, "extensions")],
    [path.join(HOME, ".config/opencode/opencode.json"), path.join(ACTIVE_BUNDLE_PATH, "opencode.json")],
  ];
  for (const [target, source] of requiredLinks) if (!checkRequiredLink(target, source)) rc = 1;
  rc = Math.max(rc, runPiExtensionsDoctor());
  rc = Math.max(rc, runPlannotatorDoctor());
  rc = Math.max(rc, runVisualArtifactDoctor());
  rc = Math.max(rc, run("node", [path.join(REPO_ROOT, "scripts/doctor-pi.mjs"), "--profile", profile.profile]));

  if (state.withLocalWebGateway) rc = runLocalWebGatewayDoctor() || rc;
  if (state.withOpencodeWeb) rc = runOpencodeWebDoctor() || rc;
  return rc;
}

