function installPlannotatorCliPlan() {
  const platform = detectPlatform();
  const asset = platform ? PLANNOTATOR_DEP.assets[platform] : null;
  planAction("info", "", "plannotator", `pinned ${PLANNOTATOR_DEP.version} (${platform ?? "unknown platform"})`);

  if (!asset) {
    const reason = `platform ${platform ?? "unknown"} not supported by pinned release`;
    planAction("skip", "", PLANNOTATOR_BINARY, reason);
    if (state.apply && state.installDeps) {
      console.error(`fail    Plannotator install: ${reason}`);
      process.exitCode = 1;
    }
    return;
  }

  if (fs.existsSync(PLANNOTATOR_BINARY)) {
    const versionResult = spawnSync(PLANNOTATOR_BINARY, ["--version"], { encoding: "utf8" });
    const installedVersion = versionResult.stdout?.trim() ?? "";
    if (
      versionResult.status === 0 &&
      installedVersion === `plannotator ${PLANNOTATOR_DEP.version}` &&
      sha256File(PLANNOTATOR_BINARY) === asset.sha256
    ) {
      planAction("noop", PLANNOTATOR_BINARY, PLANNOTATOR_BINARY, `version ${PLANNOTATOR_DEP.version} verified`);
      return;
    }
  }

  if (!state.installDeps) {
    planAction("skip", PLANNOTATOR_DEP.installer.url, PLANNOTATOR_BINARY, "--install-deps not requested");
    return;
  }

  if (!commandExists("curl") || !commandExists("bash") || !commandExists("uname")) {
    const reason = "curl/bash/uname required for Plannotator install";
    planAction("skip", PLANNOTATOR_DEP.installer.url, PLANNOTATOR_BINARY, reason);
    if (state.apply) {
      console.error(`fail    Plannotator install: ${reason}`);
      process.exitCode = 1;
    }
    return;
  }

  if (!state.apply) {
    planAction(
      "download",
      PLANNOTATOR_DEP.installer.url,
      PLANNOTATOR_BINARY,
      `would install ${PLANNOTATOR_DEP.version} with official minimal installer`,
    );
    return;
  }

  let tempHome;
  try {
    tempHome = makeTempHome();
    const installerPath = path.join(tempHome, "plannotator-install.sh");
    planAction(
      "download+verify",
      PLANNOTATOR_DEP.installer.url,
      installerPath,
      `checksum ${PLANNOTATOR_DEP.installer.sha256}`,
    );
    const installerBuffer = fetchBuffer(PLANNOTATOR_DEP.installer.url);
    const installerDigest = sha256Buffer(installerBuffer);
    if (installerDigest !== PLANNOTATOR_DEP.installer.sha256) {
      throw new Error(`installer checksum mismatch: ${installerDigest}`);
    }
    fs.writeFileSync(installerPath, installerBuffer, { mode: 0o700 });
    if (run("bash", ["-n", installerPath]) !== 0) {
      throw new Error("official installer syntax check failed");
    }

    const stagedBinDir = path.join(tempHome, ".local/bin");
    const stagedBinary = path.join(stagedBinDir, "plannotator");
    const installEnv = {
      ...process.env,
      HOME: tempHome,
      PATH: `${stagedBinDir}:${process.env.PATH ?? ""}`,
    };
    planAction("stage", installerPath, tempHome, `official minimal install v${PLANNOTATOR_DEP.version}`);
    const installRc = run(
      "bash",
      [
        installerPath,
        "--minimal",
        "--non-interactive",
        "--skip-attestation",
        "--version",
        `v${PLANNOTATOR_DEP.version}`,
      ],
      { env: installEnv, stdio: "inherit" },
    );
    if (installRc !== 0) throw new Error(`official installer exited ${installRc}`);
    if (!fs.existsSync(stagedBinary)) throw new Error("staged binary missing after install");

    const versionResult = spawnSync(stagedBinary, ["--version"], { encoding: "utf8" });
    const installedVersion = versionResult.stdout?.trim() ?? "";
    if (
      versionResult.status !== 0 ||
      installedVersion !== `plannotator ${PLANNOTATOR_DEP.version}`
    ) {
      throw new Error(
        `staged version ${installedVersion || "unknown"} does not match pinned ${PLANNOTATOR_DEP.version}`,
      );
    }
    const binaryDigest = sha256File(stagedBinary);
    if (binaryDigest !== asset.sha256) {
      throw new Error(`staged binary checksum mismatch: ${binaryDigest}`);
    }

    planAction("copy", stagedBinary, PLANNOTATOR_BINARY, "atomic binary install -> ~/.local/bin");
    fs.mkdirSync(path.dirname(PLANNOTATOR_BINARY), { recursive: true });
    const tempBinary = `${PLANNOTATOR_BINARY}.tmp-${process.pid}`;
    fs.copyFileSync(stagedBinary, tempBinary);
    fs.chmodSync(tempBinary, 0o755);
    fs.renameSync(tempBinary, PLANNOTATOR_BINARY);
    console.log(`ok      Plannotator ${PLANNOTATOR_DEP.version} installed`);
  } catch (error) {
    console.error(`fail    Plannotator install: ${error.message}`);
    process.exitCode = 1;
  } finally {
    if (tempHome) fs.rmSync(tempHome, { recursive: true, force: true });
  }
}

function installVisualArtifactCliPlan() {
  const platform = detectPlatform();
  const asset = platform ? VISUAL_ARTIFACT_DEP.assets[platform] : null;
  planAction("info", "", "visual-artifact", `pinned ${VISUAL_ARTIFACT_DEP.version} (${platform ?? "unknown platform"})`);

  if (!asset) {
    const reason = `platform ${platform ?? "unknown"} not supported by pinned release`;
    planAction("skip", "", "visual-artifact", reason);
    if (state.apply && state.installDeps) {
      console.error(`fail    visual-artifact install: ${reason}`);
      process.exitCode = 1;
    }
    return;
  }

  if (!state.installDeps) {
    planAction("skip", asset.url, VISUAL_ARTIFACT_BINARY, "--install-deps not requested");
    return;
  }

  if (!commandExists("curl") || !commandExists("tar") || !commandExists("uname")) {
    const reason = "curl/tar/uname required for external install";
    planAction("skip", "", "visual-artifact", reason);
    if (state.apply) {
      console.error(`fail    visual-artifact install: ${reason}`);
      process.exitCode = 1;
    }
    return;
  }

  if (!state.apply) {
    planAction("download", asset.url, VISUAL_ARTIFACT_BINARY, `would install ${VISUAL_ARTIFACT_DEP.version} (${asset.sha256})`);
    return;
  }

  let tempHome;
  try {
    tempHome = makeTempHome();

    planAction("download", VISUAL_ARTIFACT_DEP.installer.url, path.join(tempHome, "install.sh"), "official release installer");
    const installerBuffer = fetchBuffer(VISUAL_ARTIFACT_DEP.installer.url);
    const installerDigest = sha256Buffer(installerBuffer);
    if (installerDigest !== VISUAL_ARTIFACT_DEP.installer.sha256) {
      throw new Error(`installer checksum mismatch: ${installerDigest}`);
    }
    const installerPath = path.join(tempHome, "install.sh");
    fs.writeFileSync(installerPath, installerBuffer, { mode: 0o700 });

    const archivePath = path.join(tempHome, `visual-artifact-${platform}.tar.gz`);
    planAction("download+verify", asset.url, archivePath, `checksum ${asset.sha256}`);
    const archiveBuffer = fetchBuffer(asset.url);
    const archiveDigest = sha256Buffer(archiveBuffer);
    if (archiveDigest !== asset.sha256) {
      throw new Error(`archive checksum mismatch: ${archiveDigest}`);
    }
    fs.writeFileSync(archivePath, archiveBuffer, { mode: 0o600 });

    const manifest = {
      version: VISUAL_ARTIFACT_DEP.version,
      assets: { [platform]: pathToFileURL(archivePath).href },
    };
    const manifestPath = path.join(tempHome, "latest.json");
    writeJsonAtomic(manifestPath, manifest);

    const installEnv = {
      ...process.env,
      HOME: tempHome,
      VISUAL_ARTIFACT_MANIFEST_URL: pathToFileURL(manifestPath).href,
      VISUAL_ARTIFACT_INSTALL_DIR: path.join(tempHome, ".local/bin"),
      VISUAL_ARTIFACT_DATA_DIR: path.join(tempHome, ".local/share/visual-artifact"),
    };

    planAction("stage", installerPath, tempHome, `install ${VISUAL_ARTIFACT_DEP.version} from verified archive`);
    const installRc = run("sh", [installerPath], { env: installEnv, stdio: "inherit" });
    if (installRc !== 0) {
      throw new Error(`visual-artifact installer exited ${installRc}`);
    }

    const stagedBinary = path.join(tempHome, ".local/bin/visual-artifact");
    const stagedDataDir = path.join(tempHome, ".local/share/visual-artifact");
    const stagedRenderer = path.join(stagedDataDir, "app/out");
    const stagedVersionStamp = path.join(stagedDataDir, "VERSION");

    if (!fs.existsSync(stagedBinary)) throw new Error("staged binary missing after install");
    if (!fs.existsSync(stagedRenderer)) throw new Error("staged renderer export missing after install");

    const installedVersion = spawnSync(stagedBinary, ["--version"], { encoding: "utf8" }).stdout?.trim();
    if (installedVersion !== VISUAL_ARTIFACT_DEP.version) {
      throw new Error(`staged version ${installedVersion || "unknown"} does not match pinned ${VISUAL_ARTIFACT_DEP.version}`);
    }
    const stampedVersion = fs.existsSync(stagedVersionStamp) ? fs.readFileSync(stagedVersionStamp, "utf8").trim() : "";
    if (stampedVersion !== VISUAL_ARTIFACT_DEP.version) {
      throw new Error(`staged version stamp ${stampedVersion || "missing"} does not match pinned ${VISUAL_ARTIFACT_DEP.version}`);
    }

    planAction("copy", stagedBinary, VISUAL_ARTIFACT_BINARY, "atomic binary install -> ~/.local/bin");
    fs.mkdirSync(path.dirname(VISUAL_ARTIFACT_BINARY), { recursive: true });
    const tempBinary = `${VISUAL_ARTIFACT_BINARY}.tmp-${process.pid}`;
    fs.copyFileSync(stagedBinary, tempBinary);
    fs.chmodSync(tempBinary, 0o755);
    fs.renameSync(tempBinary, VISUAL_ARTIFACT_BINARY);

    planAction("copy", stagedRenderer, path.join(VISUAL_ARTIFACT_DATA_DIR, "app/out"), "renderer export -> ~/.local/share/visual-artifact");
    fs.mkdirSync(path.join(VISUAL_ARTIFACT_DATA_DIR, "app"), { recursive: true });
    fs.rmSync(path.join(VISUAL_ARTIFACT_DATA_DIR, "app/out"), { recursive: true, force: true });
    fs.cpSync(stagedRenderer, path.join(VISUAL_ARTIFACT_DATA_DIR, "app/out"), { recursive: true, force: true });
    fs.copyFileSync(stagedVersionStamp, path.join(VISUAL_ARTIFACT_DATA_DIR, "VERSION"));

    console.log(`ok      visual-artifact ${VISUAL_ARTIFACT_DEP.version} installed`);
  } catch (error) {
    console.error(`fail    visual-artifact install: ${error.message}`);
    process.exitCode = 1;
    return;
  } finally {
    if (tempHome) {
      try {
        fs.rmSync(tempHome, { recursive: true, force: true });
      } catch {
        // ignore cleanup failure
      }
    }
  }
}

function installDepsPlan() {
  if (!state.installDeps) return;

  const installCoreDeps = !state.withLocalWebGateway && !state.withOpencodeWeb;

  if (!state.apply) {
    if (installCoreDeps) {
      planAction("skip", "", path.join(HOME, ".config/opencode"), "--install-deps requires --apply");
    }
    if (state.withLocalWebGateway) {
      planAction("skip", "", LOCAL_WEB_GATEWAY.dir, "--install-deps requires --apply");
    }
    return;
  }

  if (installCoreDeps) {
    if (commandExists("bun")) {
      const bunRc = run("bun", ["install"], { cwd: path.join(HOME, ".config/opencode") });
      if (bunRc !== 0) {
        console.error(`fail    bun install exited ${bunRc}`);
        process.exitCode = bunRc;
      }
    } else console.log("warn    bun missing; skipped OpenCode dependency install");
  }

  if (state.withLocalWebGateway) {
    if (commandExists("npm")) {
      const npmRc = run("npm", ["ci"], { cwd: LOCAL_WEB_GATEWAY.dir });
      if (npmRc !== 0) {
        console.error(`fail    npm ci exited ${npmRc}`);
        process.exitCode = npmRc;
      }
    } else console.log("warn    npm missing; skipped local-web-gateway dependency install");
  }
}

function commandExists(command) {
  return spawnSync("sh", ["-lc", `command -v ${shellQuote(command)}`], { stdio: "ignore" }).status === 0;
}

function sha256Buffer(buffer) {
  return crypto.createHash("sha256").update(buffer).digest("hex");
}

function sha256File(file) {
  const hash = crypto.createHash("sha256");
  const fd = fs.openSync(file, "r");
  const buffer = Buffer.allocUnsafe(1024 * 1024);
  try {
    let bytesRead;
    while ((bytesRead = fs.readSync(fd, buffer, 0, buffer.length, null)) > 0) {
      hash.update(buffer.subarray(0, bytesRead));
    }
  } finally {
    fs.closeSync(fd);
  }
  return hash.digest("hex");
}

function fetchBuffer(url) {
  const result = spawnSync("curl", ["-fsSL", "--retry", "3", "--connect-timeout", "10", "--max-time", "120", url], {
    encoding: "buffer",
    maxBuffer: 50 * 1024 * 1024,
  });
  if (result.status !== 0 || !result.stdout) {
    throw new Error(`download failed: ${url}`);
  }
  return result.stdout;
}

function detectPlatform() {
  const osResult = spawnSync("uname", ["-s"], { encoding: "utf8" });
  const archResult = spawnSync("uname", ["-m"], { encoding: "utf8" });
  const rawOs = osResult.stdout?.trim().toLowerCase() ?? "";
  const rawArch = archResult.stdout?.trim().toLowerCase() ?? "";
  const osName = rawOs === "darwin" ? "macos" : rawOs === "linux" ? "linux" : null;
  const archName = rawArch === "x86_64" || rawArch === "amd64" ? "x86_64" : rawArch === "aarch64" || rawArch === "arm64" ? "aarch64" : null;
  if (!osName || !archName) return null;
  return `${osName}-${archName}`;
}

function makeTempHome() {
  const base = path.join(os.tmpdir(), `agents-install-home-${process.pid}-${Date.now()}`);
  fs.mkdirSync(base, { recursive: true });
  fs.mkdirSync(path.join(base, ".pi", "agent", "extensions"), { recursive: true });
  fs.mkdirSync(path.join(base, ".local", "bin"), { recursive: true });
  fs.mkdirSync(path.join(base, ".local", "share"), { recursive: true });
  fs.mkdirSync(path.join(base, ".agents", "skills", "visual-artifact"), { recursive: true });
  return base;
}

function writeJsonAtomic(target, value) {
  const tmp = `${target}.tmp-${process.pid}`;
  fs.writeFileSync(tmp, `${JSON.stringify(value, null, 2)}\n`);
  fs.renameSync(tmp, target);
}

function moveCleanupCandidate(target) {
  if (pathExistsOrLink(target)) {
    planAction("cleanup-backup", "", target, "approved cleanup candidate");
    if (state.apply) backupTarget(target);
  } else {
    planAction("cleanup-noop", "", target, "missing");
  }
}

function moveSymlinkCleanupCandidate(target) {
  if (!pathExistsOrLink(target)) {
    planAction("cleanup-noop", "", target, "missing");
    return;
  }
  if (!fs.lstatSync(target).isSymbolicLink()) {
    planAction("cleanup-skip", "", target, "not a symlink; preserve user-owned directory");
    return;
  }
  moveCleanupCandidate(target);
}

function cleanupCandidates() {
  moveCleanupCandidate(path.join(HOME, ".config/opencode/package-lock.json"));
  moveCleanupCandidate(path.join(HOME, ".config/opencode/command2"));
  moveCleanupCandidate(path.join(HOME, ".agents/plan-mode📝.md"));
  moveCleanupCandidate(path.join(HOME, ".agents/researcher-🤓.md"));
  moveCleanupCandidate(path.join(HOME, ".agents/Scribe.md"));
  moveSymlinkCleanupCandidate(path.join(HOME, ".config/opencode/agents"));
  moveCleanupCandidate(path.join(HOME, ".config/opencode/plugins/notes-calendar-changes.mjs"));
  moveCleanupCandidate(path.join(HOME, ".config/opencode/plugins/note-calendar-changes"));
  console.log("Stale Volta 0.74.1 package removals deferred. No package-manager state touched.");
}

function printNextSteps() {
  console.log("\nNext manual steps:");
  console.log("- Fill secrets/auth files locally; installer never migrates them.");
  console.log(`- Clone notification sounds separately: git@github.com:iurysza/notification-sounds.git -> ${NOTIFICATION_SOUNDS_DIR}`);
  if (state.withLocalWebGateway) {
    console.log("- Start local-web-gateway explicitly when ready: services/local-web-gateway/service.sh start");
    console.log("- Enable Tailscale Serve only via ~/.config/local-web-gateway/env (TAILSCALE_SERVE=1).");
  }
  if (state.withOpencodeWeb) {
    console.log("- Start opencode-web explicitly when ready: services/opencode-web/service.sh start");
    console.log(`- Optional shell integration: source ${OPENCODE_WEB.shellSnippet}`);
  }
}

function runAdoptionMode() {
  if (state.doctor || state.cleanup || state.updateSkills || state.withLocalWebGateway || state.withOpencodeWeb) {
    throw new Error("--adopt cannot be combined with --doctor, --cleanup, or service flags");
  }
  if (state.installDeps && !state.apply) throw new Error("--install-deps requires --apply");
  validateRuntimeLock(DEPENDENCIES);
  validateRuntimeExtensionCatalog({ catalog: RUNTIME_EXTENSION_CATALOG, lock: DEPENDENCIES, repoRoot: REPO_ROOT });
  const profile = resolveInstallProfile();
  if (!pathExistsOrLink(ACTIVE_BUNDLE_PATH)) throw new Error("--adopt requires an installed active profile bundle");
  const activeBundle = fs.realpathSync(ACTIVE_BUNDLE_PATH);
  const expectedBundle = renderExpectedBundle(profile, readBundleUpstreamSkillCatalog(activeBundle));
  try {
    const plan = createAdoptionPlan({
      repoRoot: REPO_ROOT,
      home: HOME,
      profileName: profile.profile,
      expectedBundle,
      activeBundle,
      lock: DEPENDENCIES,
      catalog: RUNTIME_EXTENSION_CATALOG,
    });
    console.log(formatAdoptionPlan(plan));
    if (!state.apply || !plan.hasChanges) return;
    console.log(`adoption backup: ${BACKUP_DIR}`);
    applyAdoptionPlan(plan, { backupDir: path.join(BACKUP_DIR, "adoption") });
    const childArgs = process.argv.slice(2).filter((arg) => arg !== "--adopt");
    const child = spawnSync(process.execPath, [fileURLToPath(import.meta.url), ...childArgs], {
      env: process.env,
      stdio: "inherit",
    });
    if (child.error) throw child.error;
    if (child.status !== 0) throw new Error(`adoption was locked, but profile apply failed with status ${child.status}; fix the reported error and rerun normal apply`);
  } finally {
    fs.rmSync(expectedBundle, { recursive: true, force: true });
  }
}

parseArgs(process.argv.slice(2));

if (state.adopt) {
  runAdoptionMode();
} else if (state.doctor && !state.apply && !state.installDeps && !state.cleanup) {
  process.exit(runDoctor());
} else {
  runInstallPlan();
}
if (!state.adopt && state.doctor) {
  console.log("");
  process.exitCode = runDoctor() || process.exitCode || 0;
}

#!/usr/bin/env node
import { spawnSync } from "node:child_process";
import crypto from "node:crypto";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";
import { resolveProfile } from "./lib/profile-config.mjs";
import { renderProfileBundle } from "./lib/profile-render.mjs";
import { listTrackedSkills, resolveSkillView, writeSkillSymlinks } from "./lib/skill-profile.mjs";
import { loadCachedUpstreamSkillCatalog, refreshUpstreamSkillCatalog } from "./lib/upstream-skill-catalog.mjs";
import { loadRuntimeLock, parseExactNpmSpec, validateRuntimeLock } from "./lib/runtime-lock.mjs";
import { inspectActivePackageTree, inspectGitCheckout, npmRepairSpecs, repairGitCheckout } from "./lib/package-health.mjs";
import { resolveLockedPiRoot } from "./lib/pi-smoke.mjs";
